INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$47904792$SATQ$, $SATQ$80e90694-117c-435f-b567-665c56252212$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Animals use many objects as tools to achieve goals more easily. Such goals include grooming, finding food, and protecting themselves. For a long time, people thought tool use was unique to primates. Dolphins and other animals, though, have busted the myth that tool use requires hands. Inventively, dolphins use sponges to protect their noses from scratches when foraging on the seafloor. Palm cockatoos also get creative. They use leaves to pad their beaks when opening nuts.</p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"ea51b7d4-9eca-4b92-83fe-333c32b8258d","content":"<p>To question the belief that birds are intelligent</p>"},{"id":"f553c42d-40d7-4e0b-956a-939f90c354ba","content":"<p>To compare tool use in humans with tool use in palm cockatoos</p>"},{"id":"30dfc596-218d-4a4a-9d3f-d5c3268c71ef","content":"<p>To establish that tool use doesn&rsquo;t indicate intelligence</p>"},{"id":"455059ba-6751-490c-9a08-7778abc6de32","content":"<p>To argue that a variety of animals use tools</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["455059ba-6751-490c-9a08-7778abc6de32"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most accurately states the main purpose of the text. The text first states that animals make use of objects as tools to help them achieve different goals. The text then explains that although people used to think only primates use tools, tool use by dolphins (aquatic mammals) and palm cockatoos (birds) has shown that primates are not the only animals that use tools. Thus, the main purpose of the text is to argue that a variety of animals, not just primates, use tools.</p><p>Choice A is incorrect because the text doesn&rsquo;t mention intelligence at all, focusing just on the idea that animals use tools. Further, the text mentions one kind of bird (palm cockatoos) only as an example of a non-primate that uses tools and describes its use of tools as creative, not unintelligent. Choice B is incorrect. Although the text mentions tool use in primates (a group that includes humans) and in palm cockatoos, it doesn&rsquo;t compare humans&rsquo; tool use with palm cockatoos&rsquo; tool use. The text mentions palm cockatoos only as one example out of the variety of animals that use tools and never directly mentions tool use in humans. Choice C is incorrect because the text discusses tool use but never makes any mention of intelligence. Rather than establishing that tool use doesn&rsquo;t indicate intelligence, the text describes certain tool use as inventive and creative.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"47904792","external_id":"80e90694-117c-435f-b567-665c56252212","vaultid":null,"uId":"93c8d343-f963-49c8-bf46-80629c5666c8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Animals use many objects as tools to achieve goals more easily. Such goals include grooming, finding food, and protecting themselves. For a long time, people thought tool use was unique to primates. Dolphins and other animals, though, have busted the myth that tool use requires hands. Inventively, dolphins use sponges to protect their noses from scratches when foraging on the seafloor. Palm cockatoos also get creative. They use leaves to pad their beaks when opening nuts.</p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"ea51b7d4-9eca-4b92-83fe-333c32b8258d","content":"<p>To question the belief that birds are intelligent</p>"},{"id":"f553c42d-40d7-4e0b-956a-939f90c354ba","content":"<p>To compare tool use in humans with tool use in palm cockatoos</p>"},{"id":"30dfc596-218d-4a4a-9d3f-d5c3268c71ef","content":"<p>To establish that tool use doesn&rsquo;t indicate intelligence</p>"},{"id":"455059ba-6751-490c-9a08-7778abc6de32","content":"<p>To argue that a variety of animals use tools</p>"}],"keys":["455059ba-6751-490c-9a08-7778abc6de32"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most accurately states the main purpose of the text. The text first states that animals make use of objects as tools to help them achieve different goals. The text then explains that although people used to think only primates use tools, tool use by dolphins (aquatic mammals) and palm cockatoos (birds) has shown that primates are not the only animals that use tools. Thus, the main purpose of the text is to argue that a variety of animals, not just primates, use tools.</p><p>Choice A is incorrect because the text doesn&rsquo;t mention intelligence at all, focusing just on the idea that animals use tools. Further, the text mentions one kind of bird (palm cockatoos) only as an example of a non-primate that uses tools and describes its use of tools as creative, not unintelligent. Choice B is incorrect. Although the text mentions tool use in primates (a group that includes humans) and in palm cockatoos, it doesn&rsquo;t compare humans&rsquo; tool use with palm cockatoos&rsquo; tool use. The text mentions palm cockatoos only as one example out of the variety of animals that use tools and never directly mentions tool use in humans. Choice C is incorrect because the text discusses tool use but never makes any mention of intelligence. Rather than establishing that tool use doesn&rsquo;t indicate intelligence, the text describes certain tool use as inventive and creative.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061179,"updateDate":1755117061179}$SATQ$::jsonb, 1755117061179, 1755117061179),
    ($SATQ$47955354$SATQ$, $SATQ$3df1c9a3-2e5a-429a-b8dc-f8bafc6c9918$SATQ$::uuid, $SATQ$ffde5c5a-fd52-48ce-8336-7d43397425cf$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Sumerian civilization (which lasted from around 3300 to 2000 BCE) <span aria-hidden="true">______</span><span class="sr-only">blank</span> many concepts that persist into present-day civilizations: for example, the first description of the seven-day week appears in the Sumerian <em>Epic of Gilgamesh</em>.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"7c8c1780-d12b-4b89-9d13-5e8a48e0ea54","content":"<p>transformed</p>"},{"id":"a264486c-14b3-47f1-a20b-583983e14fc1","content":"<p>introduced</p>"},{"id":"c01a83b8-9143-404b-9b15-0a60e92de320","content":"<p>inherited</p>"},{"id":"aa46103b-75c9-4d40-a393-2a3d78d96443","content":"<p>overlooked</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a264486c-14b3-47f1-a20b-583983e14fc1"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of the contributions of the Sumerian civilization. In this context, &ldquo;introduced&rdquo; means brought into practice or use. The text states that the first reference to a seven-day week appears in the Sumerian <em>Epic of Gilgamesh</em>. The text presents this information about the seven-day week as an example of a concept introduced by the Sumerian civilization that persists into present-day civilizations.&nbsp;</p><p>Choice A is incorrect because nothing in the text suggests that the Sumerian civilization &ldquo;transformed,&rdquo; or changed the nature of, concepts that persist into present-day civilizations. Instead, the text&rsquo;s presentation of a Sumerian literary work that contains the first description of the seven-day week is an example of the phenomenon described in the first half of the sentence, suggesting that the Sumerians invented many concepts that still persist.&nbsp;Choice C is incorrect because the information that a Sumerian literary work includes the first description of the seven-day week suggests that Sumerian civilization may have originated the seven-day week and other concepts that persist into present-day civilizations, not that it &ldquo;inherited&rdquo; the concepts, or received them from an ancestral figure or culture. Choice D is incorrect because the information that Sumerian civilization produced the first description of the seven-day week is presented as an example of the phenomenon described in the first half of the sentence, suggesting that Sumerian civilization originated this and other concepts that still persist, not that the Sumerians &ldquo;overlooked,&rdquo; or failed to notice or consider, such concepts. </p>$SATQ$, false, 0, $SATQ$OSP-059-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$88e42901-9536-45b9-9372-a748c80b1a5c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"47955354","external_id":"3df1c9a3-2e5a-429a-b8dc-f8bafc6c9918","vaultid":"ffde5c5a-fd52-48ce-8336-7d43397425cf","uId":"8cc8e41e-7b62-425f-8264-9c3d023efd8e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Sumerian civilization (which lasted from around 3300 to 2000 BCE) <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> many concepts that persist into present-day civilizations: for example, the first description of the seven-day week appears in the Sumerian <em>Epic of Gilgamesh</em>.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"7c8c1780-d12b-4b89-9d13-5e8a48e0ea54","content":"<p>transformed</p>"},{"id":"a264486c-14b3-47f1-a20b-583983e14fc1","content":"<p>introduced</p>"},{"id":"c01a83b8-9143-404b-9b15-0a60e92de320","content":"<p>inherited</p>"},{"id":"aa46103b-75c9-4d40-a393-2a3d78d96443","content":"<p>overlooked</p>"}],"keys":["a264486c-14b3-47f1-a20b-583983e14fc1"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of the contributions of the Sumerian civilization. In this context, &ldquo;introduced&rdquo; means brought into practice or use. The text states that the first reference to a seven-day week appears in the Sumerian <em>Epic of Gilgamesh</em>. The text presents this information about the seven-day week as an example of a concept introduced by the Sumerian civilization that persists into present-day civilizations.&nbsp;</p><p>Choice A is incorrect because nothing in the text suggests that the Sumerian civilization &ldquo;transformed,&rdquo; or changed the nature of, concepts that persist into present-day civilizations. Instead, the text&rsquo;s presentation of a Sumerian literary work that contains the first description of the seven-day week is an example of the phenomenon described in the first half of the sentence, suggesting that the Sumerians invented many concepts that still persist.&nbsp;Choice C is incorrect because the information that a Sumerian literary work includes the first description of the seven-day week suggests that Sumerian civilization may have originated the seven-day week and other concepts that persist into present-day civilizations, not that it &ldquo;inherited&rdquo; the concepts, or received them from an ancestral figure or culture. Choice D is incorrect because the information that Sumerian civilization produced the first description of the seven-day week is presented as an example of the phenomenon described in the first half of the sentence, suggesting that Sumerian civilization originated this and other concepts that still persist, not that the Sumerians &ldquo;overlooked,&rdquo; or failed to notice or consider, such concepts. </p>","parenttemplatename":"OSP-059-WIC","parenttemplateid":"","templateclusterid":"88e42901-9536-45b9-9372-a748c80b1a5c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959325,"updateDate":1691007959325}$SATQ$::jsonb, 1691007959325, 1691007959325),
    ($SATQ$479c7e82$SATQ$, $SATQ$ab4f824a-0bae-46de-b416-7eaa2476984d$SATQ$::uuid, $SATQ$04c299d0-80ab-4b38-b62f-fd5b6cb9f3e2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Although critics believed that customers would never agree to pay to pick their own produce on farms, such concerns didn&rsquo;t <span aria-hidden="true">______</span><span class="sr-only">blank</span> Booker T. Whatley&rsquo;s efforts to promote the practice. Thanks in part to Whatley&rsquo;s determined advocacy, farms that allow visitors to pick their own apples, pumpkins, and other produce can be found throughout the United States.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"07173a73-daaa-4d93-af26-bc35e6cd11d2","content":"<p>enhance</p>"},{"id":"1535b04d-2d64-4c12-96e7-c8d8e91243a2","content":"<p>hinder</p>"},{"id":"efc17ed2-5cb3-44da-9f87-367387e7ea73","content":"<p>misrepresent</p>"},{"id":"66e350a3-2f07-4f4d-bbbe-41cb4a92b9a3","content":"<p>aggravate</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["1535b04d-2d64-4c12-96e7-c8d8e91243a2"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Booker T. Whatley. In this context, &ldquo;hinder&rdquo; means hold back or obstruct. The text explains that Whatley encouraged farms to allow customers on site to pick their own produce for a fee. He did so despite critics&rsquo; concerns that the customers would never pay to do so. This context establishes that the critics&rsquo; concerns didn&rsquo;t hinder Whatley&rsquo;s efforts to promote the practice. </p><p>Choice A is incorrect. The text indicates that critics&rsquo; skepticism of the idea that customers would pay to pick their own produce didn&rsquo;t have some effect on Whatley&rsquo;s promotion of the practice. The text illustrates this assertion by describing Whatley&rsquo;s &ldquo;determined advocacy&rdquo; for the practice. This context suggests that critics&rsquo; concerns didn&rsquo;t obstruct Whatley&rsquo;s efforts, not that critics&rsquo; concerns didn&rsquo;t &ldquo;enhance,&rdquo; or increase or improve, Whatley&rsquo;s efforts.&nbsp;Choice C is incorrect because in this context, &ldquo;misrepresent&rdquo; would mean portray inaccurately, and the text includes no information relevant to the issue of how Whatley&rsquo;s efforts were portrayed by critics of the practice of charging customers to pick their own produce. Choice D is incorrect. The text indicates that critics&rsquo; skepticism of the idea that customers would pay to pick their own produce didn&rsquo;t have some effect on Whatley&rsquo;s promotion of the practice. The text illustrates this assertion by describing Whatley&rsquo;s &ldquo;determined advocacy&rdquo; for the practice. This context suggests that critics&rsquo; concerns didn&rsquo;t obstruct Whatley&rsquo;s efforts, not that critics&rsquo; concerns didn&rsquo;t &ldquo;aggravate,&rdquo; or irritate or make more severe, Whatley&rsquo;s efforts. </p>$SATQ$, false, 0, $SATQ$OSP-901-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$675d63a7-4faa-4b22-a755-214788ee167b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"479c7e82","external_id":"ab4f824a-0bae-46de-b416-7eaa2476984d","vaultid":"04c299d0-80ab-4b38-b62f-fd5b6cb9f3e2","uId":"7a55e35d-d8ae-488b-9bcc-08cdf7b74f33","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Although critics believed that customers would never agree to pay to pick their own produce on farms, such concerns didn&rsquo;t <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Booker T. Whatley&rsquo;s efforts to promote the practice. Thanks in part to Whatley&rsquo;s determined advocacy, farms that allow visitors to pick their own apples, pumpkins, and other produce can be found throughout the United States.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"07173a73-daaa-4d93-af26-bc35e6cd11d2","content":"<p>enhance</p>"},{"id":"1535b04d-2d64-4c12-96e7-c8d8e91243a2","content":"<p>hinder</p>"},{"id":"efc17ed2-5cb3-44da-9f87-367387e7ea73","content":"<p>misrepresent</p>"},{"id":"66e350a3-2f07-4f4d-bbbe-41cb4a92b9a3","content":"<p>aggravate</p>"}],"keys":["1535b04d-2d64-4c12-96e7-c8d8e91243a2"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Booker T. Whatley. In this context, &ldquo;hinder&rdquo; means hold back or obstruct. The text explains that Whatley encouraged farms to allow customers on site to pick their own produce for a fee. He did so despite critics&rsquo; concerns that the customers would never pay to do so. This context establishes that the critics&rsquo; concerns didn&rsquo;t hinder Whatley&rsquo;s efforts to promote the practice. </p><p>Choice A is incorrect. The text indicates that critics&rsquo; skepticism of the idea that customers would pay to pick their own produce didn&rsquo;t have some effect on Whatley&rsquo;s promotion of the practice. The text illustrates this assertion by describing Whatley&rsquo;s &ldquo;determined advocacy&rdquo; for the practice. This context suggests that critics&rsquo; concerns didn&rsquo;t obstruct Whatley&rsquo;s efforts, not that critics&rsquo; concerns didn&rsquo;t &ldquo;enhance,&rdquo; or increase or improve, Whatley&rsquo;s efforts.&nbsp;Choice C is incorrect because in this context, &ldquo;misrepresent&rdquo; would mean portray inaccurately, and the text includes no information relevant to the issue of how Whatley&rsquo;s efforts were portrayed by critics of the practice of charging customers to pick their own produce. Choice D is incorrect. The text indicates that critics&rsquo; skepticism of the idea that customers would pay to pick their own produce didn&rsquo;t have some effect on Whatley&rsquo;s promotion of the practice. The text illustrates this assertion by describing Whatley&rsquo;s &ldquo;determined advocacy&rdquo; for the practice. This context suggests that critics&rsquo; concerns didn&rsquo;t obstruct Whatley&rsquo;s efforts, not that critics&rsquo; concerns didn&rsquo;t &ldquo;aggravate,&rdquo; or irritate or make more severe, Whatley&rsquo;s efforts. </p>","parenttemplatename":"OSP-901-WIC","parenttemplateid":"","templateclusterid":"675d63a7-4faa-4b22-a755-214788ee167b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959354,"updateDate":1691007959354}$SATQ$::jsonb, 1691007959354, 1691007959354),
    ($SATQ$4830ab87$SATQ$, $SATQ$f6091079-bc99-40fa-9c7d-aac6bb0c1952$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The way in which individual elements are balanced within a photographic image tends to affect how viewers perceive it: symmetry tends to give the elements equal importance, asymmetry emphasizes differences, and radial balance (organizing the elements around a central point) emphasizes the center over the periphery. What a photograph conveys is therefore largely <span aria-hidden="true">______</span><span class="sr-only">blank</span> how it is balanced.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"9ba79d44-79e0-446c-bc84-2d42de2faddf","content":"<p>inhibited by</p>"},{"id":"a964d7af-8427-4532-82fa-76707bf205d1","content":"<p>contingent on</p>"},{"id":"0c177d74-fe1e-40c9-b85a-9603c5d07df6","content":"<p>obligated to</p>"},{"id":"d26cadea-2002-4b2b-9130-09568fd8d7f7","content":"<p>reserved for</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["a964d7af-8427-4532-82fa-76707bf205d1"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of visual balance in photography. In this context, "contingent on" means conditional upon, or determined by. The text indicates that different ways of balancing elements in a photograph convey different ideas to viewers (for example, symmetrical composition tends to emphasize similarity among elements, whereas asymmetry tends to emphasize difference). Thus, there is a strong connection between what a photograph conveys and how its elements are balanced. Therefore, what a photo conveys is contingent on how it is balanced.</p><p>Choice A is incorrect. In this context, "inhibited by" most nearly means hindered or undermined by. The text indicates that different ways of balancing elements in a photograph convey different ideas to viewers, thereby indicating a relationship between image balance and what is conveyed. Although this explanation is consistent with a photographer choosing asymmetrical balance even while intending to convey similarity (associated with symmetrical balance), there is nothing to indicate that messages generally are inhibited by balance. Rather the implication is that balance is a tool photographers can use to craft their messages. Choice C is incorrect. In this context, "obligated to" means duty bound toward or answerable to. In context, it would not make sense to assert that a photograph&rsquo;s message is obligated to how that photograph is balanced. Choice D is incorrect. In this context, "reserved for" most nearly means solely available to someone or held aside for some purpose. The text as a whole does not support the claim that a photograph&rsquo;s message is reserved for how that photograph is balanced.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4830ab87","external_id":"f6091079-bc99-40fa-9c7d-aac6bb0c1952","vaultid":null,"uId":"5cba5d5e-455a-4aa7-b3fa-d1c420ab759d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The way in which individual elements are balanced within a photographic image tends to affect how viewers perceive it: symmetry tends to give the elements equal importance, asymmetry emphasizes differences, and radial balance (organizing the elements around a central point) emphasizes the center over the periphery. What a photograph conveys is therefore largely <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> how it is balanced.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"9ba79d44-79e0-446c-bc84-2d42de2faddf","content":"<p>inhibited by</p>"},{"id":"a964d7af-8427-4532-82fa-76707bf205d1","content":"<p>contingent on</p>"},{"id":"0c177d74-fe1e-40c9-b85a-9603c5d07df6","content":"<p>obligated to</p>"},{"id":"d26cadea-2002-4b2b-9130-09568fd8d7f7","content":"<p>reserved for</p>"}],"keys":["a964d7af-8427-4532-82fa-76707bf205d1"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of visual balance in photography. In this context, \"contingent on\" means conditional upon, or determined by. The text indicates that different ways of balancing elements in a photograph convey different ideas to viewers (for example, symmetrical composition tends to emphasize similarity among elements, whereas asymmetry tends to emphasize difference). Thus, there is a strong connection between what a photograph conveys and how its elements are balanced. Therefore, what a photo conveys is contingent on how it is balanced.</p><p>Choice A is incorrect. In this context, \"inhibited by\" most nearly means hindered or undermined by. The text indicates that different ways of balancing elements in a photograph convey different ideas to viewers, thereby indicating a relationship between image balance and what is conveyed. Although this explanation is consistent with a photographer choosing asymmetrical balance even while intending to convey similarity (associated with symmetrical balance), there is nothing to indicate that messages generally are inhibited by balance. Rather the implication is that balance is a tool photographers can use to craft their messages. Choice C is incorrect. In this context, \"obligated to\" means duty bound toward or answerable to. In context, it would not make sense to assert that a photograph&rsquo;s message is obligated to how that photograph is balanced. Choice D is incorrect. In this context, \"reserved for\" most nearly means solely available to someone or held aside for some purpose. The text as a whole does not support the claim that a photograph&rsquo;s message is reserved for how that photograph is balanced.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323039,"updateDate":1730147323039}$SATQ$::jsonb, 1730147323039, 1730147323039),
    ($SATQ$48555763$SATQ$, $SATQ$605c9251-642f-473b-975a-7190e424e95a$SATQ$::uuid, $SATQ$03676ba5-eb12-4107-9458-4001c3c864fc$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Herman Melville&rsquo;s 1854 novel <em>The Lightning-rod Man</em>.</p>

<p>The stranger still stood in the exact middle of the cottage, where he had first planted himself. <span role="region" aria-label="Referenced Content"><u>His singularity impelled a closer scrutiny.</u></span> A lean, gloomy figure. Hair dark and lank, mattedly streaked over his brow. His sunken pitfalls of eyes were ringed by indigo halos, and played with an innocuous sort of lightning: the gleam without the bolt. The whole man was dripping. He stood in a puddle on the bare oak floor: his strange walking-stick vertically resting at his side.</p>$SATQ$, $SATQ$<p>Which choice best states the function of the underlined sentence in the overall structure of the text?</p>$SATQ$, $SATQ$[{"id":"a3793e81-6e6e-4fac-8190-57ec6e09ce12","content":"<p>It elaborates on the previous sentence&rsquo;s description of the character.</p>"},{"id":"675c5e45-1174-4b65-b1ed-b3dbe789afb9","content":"<p>It introduces the setting that is described in the sentences that follow.</p>"},{"id":"f1a39ac2-565b-4f5d-812e-0e96752567da","content":"<p>It establishes a contrast with the description in the previous sentence.</p>"},{"id":"2abf5740-ef27-4207-aacf-b8d81fb4df16","content":"<p>It sets up the character description presented in the sentences that follow.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["2abf5740-ef27-4207-aacf-b8d81fb4df16"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. This best states the function of the underlined sentence. The sentence basically says: &ldquo;He stood out, so I looked more closely at him.&rdquo; Then the rest of the text describes him in detail. &nbsp;</p><p>Choice A is incorrect. This doesn&rsquo;t state the function of the underlined sentence. The previous sentence basically says: &ldquo;He was still standing in the middle of the cottage&rdquo;&mdash;it doesn&rsquo;t include any description of the character himself. &nbsp;Choice B is incorrect. This doesn&rsquo;t state the function of the underlined sentence. The following sentences describe the character, not the setting.&nbsp;Choice C is incorrect. This doesn&rsquo;t state the function of the underlined sentence. The underlined sentence basically says: &ldquo;He stood out, so I looked more closely at him.&rdquo; The previous sentence basically says: &ldquo;He was still standing in the middle of the cottage.&rdquo; There&rsquo;s no contrast between these two sentences.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-015-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$646b0b15-3cd9-4e79-9e3f-052a5e32f158$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"48555763","external_id":"605c9251-642f-473b-975a-7190e424e95a","vaultid":"03676ba5-eb12-4107-9458-4001c3c864fc","uId":"dd64897e-af58-4a44-af71-adf471237c46","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>The following text is from Herman Melville&rsquo;s 1854 novel <em>The Lightning-rod Man</em>.</p>\n\n<p>The stranger still stood in the exact middle of the cottage, where he had first planted himself. <span role=\"region\" aria-label=\"Referenced Content\"><u>His singularity impelled a closer scrutiny.</u></span> A lean, gloomy figure. Hair dark and lank, mattedly streaked over his brow. His sunken pitfalls of eyes were ringed by indigo halos, and played with an innocuous sort of lightning: the gleam without the bolt. The whole man was dripping. He stood in a puddle on the bare oak floor: his strange walking-stick vertically resting at his side.</p>","stem":"<p>Which choice best states the function of the underlined sentence in the overall structure of the text?</p>","answerOptions":[{"id":"a3793e81-6e6e-4fac-8190-57ec6e09ce12","content":"<p>It elaborates on the previous sentence&rsquo;s description of the character.</p>"},{"id":"675c5e45-1174-4b65-b1ed-b3dbe789afb9","content":"<p>It introduces the setting that is described in the sentences that follow.</p>"},{"id":"f1a39ac2-565b-4f5d-812e-0e96752567da","content":"<p>It establishes a contrast with the description in the previous sentence.</p>"},{"id":"2abf5740-ef27-4207-aacf-b8d81fb4df16","content":"<p>It sets up the character description presented in the sentences that follow.</p>"}],"keys":["2abf5740-ef27-4207-aacf-b8d81fb4df16"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. This best states the function of the underlined sentence. The sentence basically says: &ldquo;He stood out, so I looked more closely at him.&rdquo; Then the rest of the text describes him in detail. &nbsp;</p><p>Choice A is incorrect. This doesn&rsquo;t state the function of the underlined sentence. The previous sentence basically says: &ldquo;He was still standing in the middle of the cottage&rdquo;&mdash;it doesn&rsquo;t include any description of the character himself. &nbsp;Choice B is incorrect. This doesn&rsquo;t state the function of the underlined sentence. The following sentences describe the character, not the setting.&nbsp;Choice C is incorrect. This doesn&rsquo;t state the function of the underlined sentence. The underlined sentence basically says: &ldquo;He stood out, so I looked more closely at him.&rdquo; The previous sentence basically says: &ldquo;He was still standing in the middle of the cottage.&rdquo; There&rsquo;s no contrast between these two sentences.&nbsp;</p>","parenttemplatename":"OSP-015-TSP","parenttemplateid":"","templateclusterid":"646b0b15-3cd9-4e79-9e3f-052a5e32f158","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959316,"updateDate":1691007959316}$SATQ$::jsonb, 1691007959316, 1691007959316),
    ($SATQ$48e4021d$SATQ$, $SATQ$d4330d12-8b99-4d4f-8c4d-4b2c7be0c927$SATQ$::uuid, $SATQ$41d67f4b-c38b-48a6-922b-7169debfcd01$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Holly Goldberg Sloan&rsquo;s 2017 novel <em>Short</em>.&nbsp;</p>
<blockquote>
<p>More than two years ago my parents bought a piano from some people who were moving to Utah. Mom and Dad gave it to my brothers and me for Christmas. I had to act really happy because it was such a big present, but I pretty much hated the thing from the second it was carried into the hallway upstairs, which is right next to my bedroom. The piano glared at me. It was like a songbird in a cage. It wanted to be set free.&nbsp;&nbsp;</p>
</blockquote>
<p style="text-align: right;"><span class="dap_copyright">&copy;2017 by Holly Goldberg Sloan</span></p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"9931306d-5299-488e-b8ab-c6569cc7f597","content":"<p>It explains why the narrator always wanted a piano close to her bedroom.&nbsp;</p>"},{"id":"2c5726b5-dff1-4339-b020-a063a1b42172","content":"<p>It establishes how the narrator feels about the piano.</p>"},{"id":"02967493-91bc-4dc8-8838-5ec417f6da2d","content":"<p>It suggests that the narrator&rsquo;s brothers are talented piano players.</p>"},{"id":"362a9dac-7f33-4aeb-8fd0-589ee5ffc4d7","content":"<p>It describes the event that led the narrator&rsquo;s parents to buy a piano.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["2c5726b5-dff1-4339-b020-a063a1b42172"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it best states the main purpose of the text, which is to establish the narrator&rsquo;s feelings about the piano. The narrator reveals that she &ldquo;had to act really happy&rdquo; about the piano even though she &ldquo;pretty much hated the thing&rdquo; as soon as it was placed upstairs near her bedroom. The narrator also describes the piano as glaring at her and compares it to a caged bird that wants to be set free. These details establish the narrator&rsquo;s feelings about the piano, suggesting that it makes her uneasy. </p><p>Choice A is incorrect because the text indicates that the narrator hated having the piano upstairs right next to her bedroom, not that she wanted a piano to be close to her bedroom. Choice C is incorrect because the only information provided in the text about the narrator&rsquo;s brothers is that they were given the piano along with the narrator. Choice D is incorrect because the text does not describe the event that led the narrator&rsquo;s parents to buy the piano from the people moving to Utah. Instead, the text focuses on the narrator&rsquo;s feelings about the piano after it was given to her and her brothers. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-E005$SATQ$, $SATQ$$SATQ$, $SATQ$9cea3c42-3f93-46d9-bcc2-4f7228f731e2$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"48e4021d","external_id":"d4330d12-8b99-4d4f-8c4d-4b2c7be0c927","vaultid":"41d67f4b-c38b-48a6-922b-7169debfcd01","uId":"84227a81-f371-47dd-9a1f-c05f87fb6a99","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>The following text is from Holly Goldberg Sloan&rsquo;s 2017 novel <em>Short</em>.&nbsp;</p>\n<blockquote>\n<p>More than two years ago my parents bought a piano from some people who were moving to Utah. Mom and Dad gave it to my brothers and me for Christmas. I had to act really happy because it was such a big present, but I pretty much hated the thing from the second it was carried into the hallway upstairs, which is right next to my bedroom. The piano glared at me. It was like a songbird in a cage. It wanted to be set free.&nbsp;&nbsp;</p>\n</blockquote>\n<p style=\"text-align: right;\"><span class=\"dap_copyright\">&copy;2017 by Holly Goldberg Sloan</span></p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"9931306d-5299-488e-b8ab-c6569cc7f597","content":"<p>It explains why the narrator always wanted a piano close to her bedroom.&nbsp;</p>"},{"id":"2c5726b5-dff1-4339-b020-a063a1b42172","content":"<p>It establishes how the narrator feels about the piano.</p>"},{"id":"02967493-91bc-4dc8-8838-5ec417f6da2d","content":"<p>It suggests that the narrator&rsquo;s brothers are talented piano players.</p>"},{"id":"362a9dac-7f33-4aeb-8fd0-589ee5ffc4d7","content":"<p>It describes the event that led the narrator&rsquo;s parents to buy a piano.</p>"}],"keys":["2c5726b5-dff1-4339-b020-a063a1b42172"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it best states the main purpose of the text, which is to establish the narrator&rsquo;s feelings about the piano. The narrator reveals that she &ldquo;had to act really happy&rdquo; about the piano even though she &ldquo;pretty much hated the thing&rdquo; as soon as it was placed upstairs near her bedroom. The narrator also describes the piano as glaring at her and compares it to a caged bird that wants to be set free. These details establish the narrator&rsquo;s feelings about the piano, suggesting that it makes her uneasy. </p><p>Choice A is incorrect because the text indicates that the narrator hated having the piano upstairs right next to her bedroom, not that she wanted a piano to be close to her bedroom. Choice C is incorrect because the only information provided in the text about the narrator&rsquo;s brothers is that they were given the piano along with the narrator. Choice D is incorrect because the text does not describe the event that led the narrator&rsquo;s parents to buy the piano from the people moving to Utah. Instead, the text focuses on the narrator&rsquo;s feelings about the piano after it was given to her and her brothers. </p>","parenttemplatename":"OSP-KA-TSP-E005","parenttemplateid":"","templateclusterid":"9cea3c42-3f93-46d9-bcc2-4f7228f731e2","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959374,"updateDate":1691007959374}$SATQ$::jsonb, 1691007959374, 1691007959374),
    ($SATQ$490b205f$SATQ$, $SATQ$68ddeb10-7cd9-487a-b801-947202714250$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>In editor Lisa Yaszek&rsquo;s introduction to her anthology <em>The Future Is Female! More Classic Science Fiction Stories by Women</em>, Yaszek identifies an increasing sense of <span aria-hidden="true">______</span><span class="sr-only">blank</span> feminist mode of writing in the 1970s, in contrast to many woman-authored science fiction stories of the 1920s to 1960s whose politics were less deliberately signaled.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"c5b3cd2d-018e-4542-bc47-64c638f96d26","content":"<p>a prudently</p>"},{"id":"da5637d4-a1c8-49bf-b447-41ed735ce464","content":"<p>an overtly</p>"},{"id":"7a6c0c7c-1542-412e-8689-227569550a9e","content":"<p>a cordially</p>"},{"id":"b0316cc3-1841-486e-bb91-a0559362f710","content":"<p>an inadvertently</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["da5637d4-a1c8-49bf-b447-41ed735ce464"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Yaszek&rsquo;s introduction to her science fiction anthology. In this context "overtly" means openly or without concealment. The text draws a contrast between the lack of "deliberately signaled" political themes in woman-authored science fiction from the 1920s to the 1960s and what Yaszek notes about woman-authored science fiction from the 1970s. This contrast implies that the work from the 1970s did clearly reflect feminist political themes. In other words, the text indicates that unlike women who wrote science fiction in the 1920s to the 1960s, the women who wrote science fiction in the 1970s expressed overtly feminist themes.</p><p>Choice A is incorrect. In this context "prudently" would mean cautiously, which might plausibly describe the women who wrote science fiction from the 1920s to the 1960s, in that they tended to avoid revealing their political views; however, the text contrasts these authors with the women writing science fiction in the 1970s, thereby suggesting that the authors writing in the 1970s were not restrained in that way. Choice C is incorrect because in this context "cordially" would mean politely, and nothing in the text indicates that politeness was a significant factor for women writing science fiction either from the 1920s to the 1960s or in the 1970s. The text draws a contrast between the lack of "deliberately signaled" political themes in woman-authored science fiction from the 1920s to the 1960s and what Yaszek notes about woman-authored science fiction from the 1970s. It&rsquo;s unclear how "less deliberately signaled" politics and an increasing sense of politeness toward feminism would constitute a meaningful contrast. Choice D is incorrect because in this context, "inadvertently" would mean unintentionally, and nothing in the text suggests that Yaszek thought the feminist elements of the woman-authored science fiction from the 1970s arose without deliberate effort.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"490b205f","external_id":"68ddeb10-7cd9-487a-b801-947202714250","vaultid":null,"uId":"d9d843b4-242f-4756-aee1-80c85922b55e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>In editor Lisa Yaszek&rsquo;s introduction to her anthology <em>The Future Is Female! More Classic Science Fiction Stories by Women</em>, Yaszek identifies an increasing sense of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> feminist mode of writing in the 1970s, in contrast to many woman-authored science fiction stories of the 1920s to 1960s whose politics were less deliberately signaled.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"c5b3cd2d-018e-4542-bc47-64c638f96d26","content":"<p>a prudently</p>"},{"id":"da5637d4-a1c8-49bf-b447-41ed735ce464","content":"<p>an overtly</p>"},{"id":"7a6c0c7c-1542-412e-8689-227569550a9e","content":"<p>a cordially</p>"},{"id":"b0316cc3-1841-486e-bb91-a0559362f710","content":"<p>an inadvertently</p>"}],"keys":["da5637d4-a1c8-49bf-b447-41ed735ce464"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Yaszek&rsquo;s introduction to her science fiction anthology. In this context \"overtly\" means openly or without concealment. The text draws a contrast between the lack of \"deliberately signaled\" political themes in woman-authored science fiction from the 1920s to the 1960s and what Yaszek notes about woman-authored science fiction from the 1970s. This contrast implies that the work from the 1970s did clearly reflect feminist political themes. In other words, the text indicates that unlike women who wrote science fiction in the 1920s to the 1960s, the women who wrote science fiction in the 1970s expressed overtly feminist themes.</p><p>Choice A is incorrect. In this context \"prudently\" would mean cautiously, which might plausibly describe the women who wrote science fiction from the 1920s to the 1960s, in that they tended to avoid revealing their political views; however, the text contrasts these authors with the women writing science fiction in the 1970s, thereby suggesting that the authors writing in the 1970s were not restrained in that way. Choice C is incorrect because in this context \"cordially\" would mean politely, and nothing in the text indicates that politeness was a significant factor for women writing science fiction either from the 1920s to the 1960s or in the 1970s. The text draws a contrast between the lack of \"deliberately signaled\" political themes in woman-authored science fiction from the 1920s to the 1960s and what Yaszek notes about woman-authored science fiction from the 1970s. It&rsquo;s unclear how \"less deliberately signaled\" politics and an increasing sense of politeness toward feminism would constitute a meaningful contrast. Choice D is incorrect because in this context, \"inadvertently\" would mean unintentionally, and nothing in the text suggests that Yaszek thought the feminist elements of the woman-authored science fiction from the 1970s arose without deliberate effort.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323052,"updateDate":1730147323052}$SATQ$::jsonb, 1730147323052, 1730147323052),
    ($SATQ$4974b053$SATQ$, $SATQ$515f70fd-1a8a-4b59-9fc4-a493d3ed0618$SATQ$::uuid, $SATQ$a3ca1e95-c5d9-4e43-bbd6-c08b8ea94fd1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Although science fiction was dominated mostly by white male authors when Octavia Butler, a Black woman, began writing, she did not view the genre as <span aria-hidden="true">______</span><span class="sr-only">blank</span>: Butler broke into the field with the publication of several short stories and her 1976 novel <em>Patternmaster</em>, and she later became the first science fiction writer to win a prestigious MacArthur Fellowship.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"8fca3ae3-dbea-4583-a5dc-c615ea219c18","content":"<p>legitimate</p>"},{"id":"04e76167-a5f6-41bb-994f-574211ed792c","content":"<p>impenetrable</p>"},{"id":"5affa566-e30c-4206-9ac9-4868ffa87710","content":"<p>compelling</p>"},{"id":"6923eeef-4f14-4257-ac0a-6b62ccb3eaa4","content":"<p>indecipherable</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["04e76167-a5f6-41bb-994f-574211ed792c"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the discussion of Octavia Butler&rsquo;s career. In this context, &ldquo;impenetrable&rdquo; means impossible to enter. The text indicates that the field of science fiction was dominated by white males when Butler, a Black woman, started writing, but she published several science fiction short stories and a novel and later won a prestigious award; that is, Butler pursued science fiction writing and had success. This context suggests that Butler didn&rsquo;t view the genre as impossible to enter. </p><p>Choice A is incorrect. In this context, &ldquo;legitimate&rdquo; would mean genuinely good or valid. Nothing in the text suggests that Butler didn&rsquo;t think the science fiction genre was good or valid; in fact, it indicates that she pursued and made a successful career of publishing work in that field. Choice C is incorrect. In this context, &ldquo;compelling&rdquo; would mean attracting or demanding attention. The text indicates that Butler chose to write science fiction, so it wouldn&rsquo;t make sense to say that she didn&rsquo;t see the field as drawing her attention. Choice D is incorrect. To say that Butler didn&rsquo;t consider science fiction &ldquo;indecipherable,&rdquo; or impossible to understand, would suggest that Butler did understand it. However, the text doesn&rsquo;t address Butler&rsquo;s ability to interpret works in the genre; rather, it focuses on Butler&rsquo;s successful pursuit of writing science fiction. </p>$SATQ$, false, 0, $SATQ$OSP-904-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$1695eb4d-7bab-4c02-a0f3-cc357b7b9ee6$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4974b053","external_id":"515f70fd-1a8a-4b59-9fc4-a493d3ed0618","vaultid":"a3ca1e95-c5d9-4e43-bbd6-c08b8ea94fd1","uId":"19a877a3-45a3-4d92-92dc-ef40e60bad6d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Although science fiction was dominated mostly by white male authors when Octavia Butler, a Black woman, began writing, she did not view the genre as <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>: Butler broke into the field with the publication of several short stories and her 1976 novel <em>Patternmaster</em>, and she later became the first science fiction writer to win a prestigious MacArthur Fellowship.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"8fca3ae3-dbea-4583-a5dc-c615ea219c18","content":"<p>legitimate</p>"},{"id":"04e76167-a5f6-41bb-994f-574211ed792c","content":"<p>impenetrable</p>"},{"id":"5affa566-e30c-4206-9ac9-4868ffa87710","content":"<p>compelling</p>"},{"id":"6923eeef-4f14-4257-ac0a-6b62ccb3eaa4","content":"<p>indecipherable</p>"}],"keys":["04e76167-a5f6-41bb-994f-574211ed792c"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the discussion of Octavia Butler&rsquo;s career. In this context, &ldquo;impenetrable&rdquo; means impossible to enter. The text indicates that the field of science fiction was dominated by white males when Butler, a Black woman, started writing, but she published several science fiction short stories and a novel and later won a prestigious award; that is, Butler pursued science fiction writing and had success. This context suggests that Butler didn&rsquo;t view the genre as impossible to enter. </p><p>Choice A is incorrect. In this context, &ldquo;legitimate&rdquo; would mean genuinely good or valid. Nothing in the text suggests that Butler didn&rsquo;t think the science fiction genre was good or valid; in fact, it indicates that she pursued and made a successful career of publishing work in that field. Choice C is incorrect. In this context, &ldquo;compelling&rdquo; would mean attracting or demanding attention. The text indicates that Butler chose to write science fiction, so it wouldn&rsquo;t make sense to say that she didn&rsquo;t see the field as drawing her attention. Choice D is incorrect. To say that Butler didn&rsquo;t consider science fiction &ldquo;indecipherable,&rdquo; or impossible to understand, would suggest that Butler did understand it. However, the text doesn&rsquo;t address Butler&rsquo;s ability to interpret works in the genre; rather, it focuses on Butler&rsquo;s successful pursuit of writing science fiction. </p>","parenttemplatename":"OSP-904-WIC","parenttemplateid":"","templateclusterid":"1695eb4d-7bab-4c02-a0f3-cc357b7b9ee6","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959354,"updateDate":1691007959354}$SATQ$::jsonb, 1691007959354, 1691007959354),
    ($SATQ$49bbe4d7$SATQ$, $SATQ$3e7eb38e-32c1-4df3-b144-b9d1d5beac6c$SATQ$::uuid, $SATQ$6d3b9600-abd7-480f-a98c-5ba7e7bd21c8$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>For painter Jacob Lawrence, being <span aria-hidden="true">______</span><span class="sr-only">blank</span> was an important part of the artistic process. Because he paid close attention to all the details of his Harlem neighborhood, Lawrence&rsquo;s artwork captured nuances in the beauty and vitality of the Black experience during the Harlem Renaissance and the Great Migration.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"7593a930-54ed-4d14-b980-790845175f87","content":"<p>skeptical</p>"},{"id":"d2b49534-23b9-48c1-b9f7-e09804b1ebf2","content":"<p>observant</p>"},{"id":"f184d772-634a-4c89-87bd-c9038bf1563b","content":"<p>critical</p>"},{"id":"176ea416-b0c6-4bfd-872b-856c48732514","content":"<p>confident</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["d2b49534-23b9-48c1-b9f7-e09804b1ebf2"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Jacob Lawrence&rsquo;s artistic process. In this context, &ldquo;observant&rdquo; means watchful and perceptive. The text emphasizes that the &ldquo;close attention&rdquo; Lawrence paid to &ldquo;all the details&rdquo; of his neighborhood allowed him to reflect subtle elements of &ldquo;the beauty and vitality of the Black experience&rdquo; in his artwork. This context indicates that being observant of his surroundings was an important part of Lawrence&rsquo;s work as an artist. </p><p>Choice A is incorrect because the text gives no indication that Lawrence was &ldquo;skeptical,&rdquo; or had an attitude of doubt in general or about particular things, let alone that skepticism was important to him as an artist. Rather than indicating that he was skeptical, the text focuses on how Lawrence paid careful attention to everything around him and reflected his observations in his artwork. Choice C is incorrect because the text gives no indication that Lawrence was &ldquo;critical,&rdquo; which in this context would mean inclined to criticize harshly or unfairly. Rather than indicating that Lawrence found fault in things, the text suggests that he paid careful attention to everything around him and that his artwork reflects this careful attention. Choice D is incorrect because the text doesn&rsquo;t suggest that Lawrence was &ldquo;confident,&rdquo; or self-assured. Rather than addressing how Lawrence felt about himself and how that feeling affected his artistic process, the text emphasizes the careful attention Lawrence paid to everything around him&mdash;attention that allowed him to capture subtle elements of a particular place and time in his artwork. </p>$SATQ$, false, 0, $SATQ$OSP-980-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$dc9484a7-a6d6-43be-8e63-02378c341a2c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"49bbe4d7","external_id":"3e7eb38e-32c1-4df3-b144-b9d1d5beac6c","vaultid":"6d3b9600-abd7-480f-a98c-5ba7e7bd21c8","uId":"b122dbee-7c5a-4ef4-aed7-643fadf1f6b8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>For painter Jacob Lawrence, being <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> was an important part of the artistic process. Because he paid close attention to all the details of his Harlem neighborhood, Lawrence&rsquo;s artwork captured nuances in the beauty and vitality of the Black experience during the Harlem Renaissance and the Great Migration.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"7593a930-54ed-4d14-b980-790845175f87","content":"<p>skeptical</p>"},{"id":"d2b49534-23b9-48c1-b9f7-e09804b1ebf2","content":"<p>observant</p>"},{"id":"f184d772-634a-4c89-87bd-c9038bf1563b","content":"<p>critical</p>"},{"id":"176ea416-b0c6-4bfd-872b-856c48732514","content":"<p>confident</p>"}],"keys":["d2b49534-23b9-48c1-b9f7-e09804b1ebf2"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of Jacob Lawrence&rsquo;s artistic process. In this context, &ldquo;observant&rdquo; means watchful and perceptive. The text emphasizes that the &ldquo;close attention&rdquo; Lawrence paid to &ldquo;all the details&rdquo; of his neighborhood allowed him to reflect subtle elements of &ldquo;the beauty and vitality of the Black experience&rdquo; in his artwork. This context indicates that being observant of his surroundings was an important part of Lawrence&rsquo;s work as an artist. </p><p>Choice A is incorrect because the text gives no indication that Lawrence was &ldquo;skeptical,&rdquo; or had an attitude of doubt in general or about particular things, let alone that skepticism was important to him as an artist. Rather than indicating that he was skeptical, the text focuses on how Lawrence paid careful attention to everything around him and reflected his observations in his artwork. Choice C is incorrect because the text gives no indication that Lawrence was &ldquo;critical,&rdquo; which in this context would mean inclined to criticize harshly or unfairly. Rather than indicating that Lawrence found fault in things, the text suggests that he paid careful attention to everything around him and that his artwork reflects this careful attention. Choice D is incorrect because the text doesn&rsquo;t suggest that Lawrence was &ldquo;confident,&rdquo; or self-assured. Rather than addressing how Lawrence felt about himself and how that feeling affected his artistic process, the text emphasizes the careful attention Lawrence paid to everything around him&mdash;attention that allowed him to capture subtle elements of a particular place and time in his artwork. </p>","parenttemplatename":"OSP-980-WIC","parenttemplateid":"","templateclusterid":"dc9484a7-a6d6-43be-8e63-02378c341a2c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959358,"updateDate":1691007959358}$SATQ$::jsonb, 1691007959358, 1691007959358),
    ($SATQ$4a2b2535$SATQ$, $SATQ$1254ceb3-3b92-41be-b677-6482492613a6$SATQ$::uuid, $SATQ$3c363503-4318-4d9e-be32-5f002e31eea8$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>A brief book review cannot fully convey the <span aria-hidden="true">______</span><span class="sr-only">blank</span> of Olga Tokarczuk&rsquo;s novel <em>The Books of Jacob</em>, with its enormous cast of characters, its complicated, wandering plot, and its page numbers that count backward (beginning at 965 and ending at 1).</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"b36901c7-0bac-468b-b239-4f5aa98bd54e","content":"<p>accuracy</p>"},{"id":"37b89118-c4de-4d31-bcfa-a3c56bdf6a4a","content":"<p>inactivity</p>"},{"id":"50d25523-eec2-43ca-8897-9b5d75552fb1","content":"<p>complexity</p>"},{"id":"fa9ffd91-d3ae-4575-9cd5-239d823030bf","content":"<p>restraint</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["50d25523-eec2-43ca-8897-9b5d75552fb1"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of Olga Tokarczuk&rsquo;s novel <em>The Books of Jacob</em>. As used in this context, &ldquo;complexity&rdquo; means having many complicated parts that when taken as a whole are difficult to follow or explain. The text indicates that <em>The Books of Jacob</em> has a large cast of characters, a complicated and wandering plot (that is, a plot that is difficult to follow), and reverse page numbering. Together, these features make up a novel that&rsquo;s challenging to read and summarize. This context supports the idea that a brief book review can&rsquo;t do justice to the novel&rsquo;s complexity. </p><p>Choice A is incorrect. Although the word &ldquo;accuracy,&rdquo; or being free from error or falsehood, can sometimes be used to describe a novel, the text doesn&rsquo;t discuss whether Tokarczuk&rsquo;s novel has this quality. Instead, the text describes the novel as having a large cast of characters, a difficult-to-follow plot, and reverse page numbering. These features suggest complexity, not accuracy. Choice B is incorrect because &ldquo;inactivity&rdquo; means being in a state of idleness or doing nothing, neither of which would make sense in this context. The text describes Tokarczuk&rsquo;s novel, and although it&rsquo;s possible the novel could portray its characters as inactive, it wouldn&rsquo;t make sense to describe the novel itself as such.&nbsp;Choice D is incorrect because in this context &ldquo;restraint&rdquo; would mean holding back or showing self-control, and the text doesn&rsquo;t indicate that Tokarczuk&rsquo;s novel has either of these qualities. In fact, the features of the novel that the text describes, such as a large cast of characters, a complicated and wandering plot, and reverse page numbering, suggest excess and complexity, not restraint. </p>$SATQ$, false, 0, $SATQ$OSP-025-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$74ee2532-4409-4f87-8ea2-cbaf6e579d37$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4a2b2535","external_id":"1254ceb3-3b92-41be-b677-6482492613a6","vaultid":"3c363503-4318-4d9e-be32-5f002e31eea8","uId":"23fa283f-b020-457c-af95-f15096eb3a77","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>A brief book review cannot fully convey the <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> of Olga Tokarczuk&rsquo;s novel <em>The Books of Jacob</em>, with its enormous cast of characters, its complicated, wandering plot, and its page numbers that count backward (beginning at 965 and ending at 1).</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"b36901c7-0bac-468b-b239-4f5aa98bd54e","content":"<p>accuracy</p>"},{"id":"37b89118-c4de-4d31-bcfa-a3c56bdf6a4a","content":"<p>inactivity</p>"},{"id":"50d25523-eec2-43ca-8897-9b5d75552fb1","content":"<p>complexity</p>"},{"id":"fa9ffd91-d3ae-4575-9cd5-239d823030bf","content":"<p>restraint</p>"}],"keys":["50d25523-eec2-43ca-8897-9b5d75552fb1"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of Olga Tokarczuk&rsquo;s novel <em>The Books of Jacob</em>. As used in this context, &ldquo;complexity&rdquo; means having many complicated parts that when taken as a whole are difficult to follow or explain. The text indicates that <em>The Books of Jacob</em> has a large cast of characters, a complicated and wandering plot (that is, a plot that is difficult to follow), and reverse page numbering. Together, these features make up a novel that&rsquo;s challenging to read and summarize. This context supports the idea that a brief book review can&rsquo;t do justice to the novel&rsquo;s complexity. </p><p>Choice A is incorrect. Although the word &ldquo;accuracy,&rdquo; or being free from error or falsehood, can sometimes be used to describe a novel, the text doesn&rsquo;t discuss whether Tokarczuk&rsquo;s novel has this quality. Instead, the text describes the novel as having a large cast of characters, a difficult-to-follow plot, and reverse page numbering. These features suggest complexity, not accuracy. Choice B is incorrect because &ldquo;inactivity&rdquo; means being in a state of idleness or doing nothing, neither of which would make sense in this context. The text describes Tokarczuk&rsquo;s novel, and although it&rsquo;s possible the novel could portray its characters as inactive, it wouldn&rsquo;t make sense to describe the novel itself as such.&nbsp;Choice D is incorrect because in this context &ldquo;restraint&rdquo; would mean holding back or showing self-control, and the text doesn&rsquo;t indicate that Tokarczuk&rsquo;s novel has either of these qualities. In fact, the features of the novel that the text describes, such as a large cast of characters, a complicated and wandering plot, and reverse page numbering, suggest excess and complexity, not restraint. </p>","parenttemplatename":"OSP-025-WIC","parenttemplateid":"","templateclusterid":"74ee2532-4409-4f87-8ea2-cbaf6e579d37","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959318,"updateDate":1691007959318}$SATQ$::jsonb, 1691007959318, 1691007959318),
    ($SATQ$4b4ab04e$SATQ$, $SATQ$c9e092ea-db85-4654-9843-1ccec316a12a$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 1</strong></span></p>
<p>Mycoprotein is a fungal biomass that can be eaten as an alternative to meat. Studies of the environmental impact of its manufacture generally agree it is lower than that of beef and closer to that of chicken or pork. But the expense of producing mycoprotein restricts its availability to a few countries with postindustrial economies. Knowing that cost reductions would expand access to mycoprotein, biochemists are exploring solutions, such as a cheaper substrate to feed the mycoprotein as it grows.</p>
<p>&nbsp;</p>
<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 2</strong></span></p>
<p>Cattle farming is a principal cause of global deforestation, and a study by Florian Humpen&ouml;der and his colleagues found that replacing 20% of beef consumption worldwide with consumption of mycoprotein would cut deforestation by half if accomplished over the next thirty years. However, this would likely involve only a small change in agricultural water consumption, since water once dedicated to raising cattle would be diverted to raising crops instead.</p>$SATQ$, $SATQ$<p>Based on the texts, how would the author of Text 1 most likely respond to the study findings mentioned in Text 2?</p>$SATQ$, $SATQ$[{"id":"c1f4fed1-3633-443c-80ed-e347120c8d65","content":"<p>By emphasizing that since agricultural water consumption would remain static in the event of replacing beef consumption with mycoprotein consumption, an effort must be made to substitute mycoprotein for chicken and pork in diets as well</p>"},{"id":"3acbc7d3-9021-41df-a8c3-15ae3ebbbf21","content":"<p>By asserting that the development of a more inexpensive substrate for mycoprotein production would contribute to the goal of decreasing worldwide deforestation over time</p>"},{"id":"8474a384-aa0a-4617-9571-23c93d39e2ef","content":"<p>By noting that most people would be more likely to use mycoprotein as a substitute for chicken or pork in their diets than as a substitute for beef</p>"},{"id":"1e3c8e29-c9f6-48b7-9343-5b2c0addb8a3","content":"<p>By pointing out that some countries are responsible for greater deforestation than others and thus, to have any significant effect on the environment, will have to replace more than 20% of their beef consumption with mycoprotein</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["3acbc7d3-9021-41df-a8c3-15ae3ebbbf21"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it reflects how the author of Text 1 would most likely respond to the study findings described in Text 2. The author of Text 2 discusses a study by Florian Humpen&ouml;der and his colleagues that found that deforestation would be reduced by half over the next thirty years if 20% of the beef consumed worldwide were replaced with mycoprotein. The author of Text 1 points out that mycoprotein is not widely available because of its high production cost, but goes on to note that this problem could be addressed by the creation of a cheaper substrate to feed mycoprotein. This suggests that the author of Text 1 would assert that the development of a less expensive mycoprotein substrate would contribute to the reduction in deforestation described in the study findings discussed in Text 2: if reducing the cost of mycoprotein increases people&rsquo;s access to it, then mycoprotein may be able to replace beef in more people&rsquo;s diets, thereby reducing the deforestation associated with beef production.</p><p>Choice A is incorrect because the author of Text 1 indicates that the environmental impact of mycoprotein production is close to that of chicken or pork production, so there is no reason to think that the author would assert that replacing chicken or pork with mycoprotein would be environmentally beneficial: such a replacement would not lessen the total environmental impact of food manufacture. Additionally, the specific issue of agricultural water consumption is never mentioned in Text 1, so there is no evidence indicating what the author of Text 1 would say about that issue. Choice C is incorrect. Although Text 1 does compare the environmental effects of producing mycoprotein to those of producing chicken or pork, nothing in Text 1 suggests that the author believes that people are more likely to replace chicken or pork with mycoprotein than they are to replace beef with mycoprotein. Choice D is incorrect because Text 1 makes no mention of countries&rsquo; varying contributions to deforestation, so there is no evidence that the author of Text 1 would respond to the finding described in Text 2 by saying that some countries will have to replace more than 20% of their beef consumption with mycoprotein.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4b4ab04e","external_id":"c9e092ea-db85-4654-9843-1ccec316a12a","vaultid":null,"uId":"4384aec3-a8ba-474d-9355-f723938ded5a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 1</strong></span></p>\n<p>Mycoprotein is a fungal biomass that can be eaten as an alternative to meat. Studies of the environmental impact of its manufacture generally agree it is lower than that of beef and closer to that of chicken or pork. But the expense of producing mycoprotein restricts its availability to a few countries with postindustrial economies. Knowing that cost reductions would expand access to mycoprotein, biochemists are exploring solutions, such as a cheaper substrate to feed the mycoprotein as it grows.</p>\n<p>&nbsp;</p>\n<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 2</strong></span></p>\n<p>Cattle farming is a principal cause of global deforestation, and a study by Florian Humpen&ouml;der and his colleagues found that replacing 20% of beef consumption worldwide with consumption of mycoprotein would cut deforestation by half if accomplished over the next thirty years. However, this would likely involve only a small change in agricultural water consumption, since water once dedicated to raising cattle would be diverted to raising crops instead.</p>","stem":"<p>Based on the texts, how would the author of Text 1 most likely respond to the study findings mentioned in Text 2?</p>","answerOptions":[{"id":"c1f4fed1-3633-443c-80ed-e347120c8d65","content":"<p>By emphasizing that since agricultural water consumption would remain static in the event of replacing beef consumption with mycoprotein consumption, an effort must be made to substitute mycoprotein for chicken and pork in diets as well</p>"},{"id":"3acbc7d3-9021-41df-a8c3-15ae3ebbbf21","content":"<p>By asserting that the development of a more inexpensive substrate for mycoprotein production would contribute to the goal of decreasing worldwide deforestation over time</p>"},{"id":"8474a384-aa0a-4617-9571-23c93d39e2ef","content":"<p>By noting that most people would be more likely to use mycoprotein as a substitute for chicken or pork in their diets than as a substitute for beef</p>"},{"id":"1e3c8e29-c9f6-48b7-9343-5b2c0addb8a3","content":"<p>By pointing out that some countries are responsible for greater deforestation than others and thus, to have any significant effect on the environment, will have to replace more than 20% of their beef consumption with mycoprotein</p>"}],"keys":["3acbc7d3-9021-41df-a8c3-15ae3ebbbf21"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it reflects how the author of Text 1 would most likely respond to the study findings described in Text 2. The author of Text 2 discusses a study by Florian Humpen&ouml;der and his colleagues that found that deforestation would be reduced by half over the next thirty years if 20% of the beef consumed worldwide were replaced with mycoprotein. The author of Text 1 points out that mycoprotein is not widely available because of its high production cost, but goes on to note that this problem could be addressed by the creation of a cheaper substrate to feed mycoprotein. This suggests that the author of Text 1 would assert that the development of a less expensive mycoprotein substrate would contribute to the reduction in deforestation described in the study findings discussed in Text 2: if reducing the cost of mycoprotein increases people&rsquo;s access to it, then mycoprotein may be able to replace beef in more people&rsquo;s diets, thereby reducing the deforestation associated with beef production.</p><p>Choice A is incorrect because the author of Text 1 indicates that the environmental impact of mycoprotein production is close to that of chicken or pork production, so there is no reason to think that the author would assert that replacing chicken or pork with mycoprotein would be environmentally beneficial: such a replacement would not lessen the total environmental impact of food manufacture. Additionally, the specific issue of agricultural water consumption is never mentioned in Text 1, so there is no evidence indicating what the author of Text 1 would say about that issue. Choice C is incorrect. Although Text 1 does compare the environmental effects of producing mycoprotein to those of producing chicken or pork, nothing in Text 1 suggests that the author believes that people are more likely to replace chicken or pork with mycoprotein than they are to replace beef with mycoprotein. Choice D is incorrect because Text 1 makes no mention of countries&rsquo; varying contributions to deforestation, so there is no evidence that the author of Text 1 would respond to the finding described in Text 2 by saying that some countries will have to replace more than 20% of their beef consumption with mycoprotein.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323033,"updateDate":1730147323033}$SATQ$::jsonb, 1730147323033, 1730147323033),
    ($SATQ$4b54bbf0$SATQ$, $SATQ$adc6efb5-1b1e-4fc4-b769-b2f90520e6a7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In the 2010s, the price of pop music cassette tapes from the 1980s and 1990s rose dramatically, which had the counterintuitive effect of <span aria-hidden="true">______</span><span class="sr-only">blank</span> demand: buyers who hadn&rsquo;t previously wanted to purchase vintage cassettes thronged the market, believing prices would continue to rise and the tapes could be resold later at a profit.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"00123193-640b-48a5-8cc0-2bc970ca3702","content":"<p>exploiting</p>"},{"id":"bd69da82-203e-4e70-96fc-70e7c36af040","content":"<p>monetizing</p>"},{"id":"0e1401e6-5a1c-4ab7-9981-4d810dbd74b4","content":"<p>appraising</p>"},{"id":"93c644f0-7fd4-4112-93b8-509db17108ed","content":"<p>engendering</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["93c644f0-7fd4-4112-93b8-509db17108ed"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of how rising prices affected demand for vintage cassette tapes. In this context, "engendering" means producing or causing to exist. The text indicates that the effect of a dramatic increase in the price of vintage cassettes was counterintuitive, or contrary to what would typically be expected. Generally, when prices rise, demand falls&mdash;but the text indicates that in this case, buyers who previously had no interest in cassettes "thronged the market" (that is, many of them began purchasing cassettes) because they saw the cassettes as potential investments. This context conveys that the rising prices surprisingly produced significant demand, producing many new buyers for vintage cassettes.</p><p>Choice A is incorrect because the text focuses on a rise in prices of vintage cassettes, and it wouldn&rsquo;t make sense to describe the price increase itself&mdash;rather than sellers of vintage cassettes&mdash;as "exploiting," or unfairly or selfishly taking advantage of, demand. Further, wanting to take advantage of new demand would be a motivation for a price increase, not a counterintuitive effect of it. Choice B is incorrect. In this context, "monetizing" would mean utilizing as a source of profit, and it wouldn&rsquo;t make sense to describe a price increase itself, rather than sellers of vintage cassettes, as using demand as a source of profit; moreover, seeking to profit when there&rsquo;s new demand would be a reason for price increases, not a counterintuitive effect of them. Choice C is incorrect. In this context, "appraising" would mean assessing the value or significance of something. The text focuses on a rise in prices of vintage cassettes, and while it would be reasonable to suggest that sellers might have appraised demand for those cassettes, it wouldn&rsquo;t make sense to suggest that a price increase itself could do such an assessment; moreover, an appraisal of demand would most likely precede a price increase rather than be an effect of it.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4b54bbf0","external_id":"adc6efb5-1b1e-4fc4-b769-b2f90520e6a7","vaultid":null,"uId":"ba4b7579-517c-4e3c-86f5-8729b8d18a55","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>In the 2010s, the price of pop music cassette tapes from the 1980s and 1990s rose dramatically, which had the counterintuitive effect of <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> demand: buyers who hadn&rsquo;t previously wanted to purchase vintage cassettes thronged the market, believing prices would continue to rise and the tapes could be resold later at a profit.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"00123193-640b-48a5-8cc0-2bc970ca3702","content":"<p>exploiting</p>"},{"id":"bd69da82-203e-4e70-96fc-70e7c36af040","content":"<p>monetizing</p>"},{"id":"0e1401e6-5a1c-4ab7-9981-4d810dbd74b4","content":"<p>appraising</p>"},{"id":"93c644f0-7fd4-4112-93b8-509db17108ed","content":"<p>engendering</p>"}],"keys":["93c644f0-7fd4-4112-93b8-509db17108ed"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of how rising prices affected demand for vintage cassette tapes. In this context, \"engendering\" means producing or causing to exist. The text indicates that the effect of a dramatic increase in the price of vintage cassettes was counterintuitive, or contrary to what would typically be expected. Generally, when prices rise, demand falls&mdash;but the text indicates that in this case, buyers who previously had no interest in cassettes \"thronged the market\" (that is, many of them began purchasing cassettes) because they saw the cassettes as potential investments. This context conveys that the rising prices surprisingly produced significant demand, producing many new buyers for vintage cassettes.</p><p>Choice A is incorrect because the text focuses on a rise in prices of vintage cassettes, and it wouldn&rsquo;t make sense to describe the price increase itself&mdash;rather than sellers of vintage cassettes&mdash;as \"exploiting,\" or unfairly or selfishly taking advantage of, demand. Further, wanting to take advantage of new demand would be a motivation for a price increase, not a counterintuitive effect of it. Choice B is incorrect. In this context, \"monetizing\" would mean utilizing as a source of profit, and it wouldn&rsquo;t make sense to describe a price increase itself, rather than sellers of vintage cassettes, as using demand as a source of profit; moreover, seeking to profit when there&rsquo;s new demand would be a reason for price increases, not a counterintuitive effect of them. Choice C is incorrect. In this context, \"appraising\" would mean assessing the value or significance of something. The text focuses on a rise in prices of vintage cassettes, and while it would be reasonable to suggest that sellers might have appraised demand for those cassettes, it wouldn&rsquo;t make sense to suggest that a price increase itself could do such an assessment; moreover, an appraisal of demand would most likely precede a price increase rather than be an effect of it.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061191,"updateDate":1755117061191}$SATQ$::jsonb, 1755117061191, 1755117061191),
    ($SATQ$4b8244ca$SATQ$, $SATQ$decacff8-b174-4cdb-9bcb-5c5714d5025d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>One challenge of generating electricity from ocean waves is that wave power isn&rsquo;t <span aria-hidden="true">______</span><span class="sr-only">blank</span>: it varies in unpredictable ways that pose technological and planning problems for electricity generation.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"93e22736-7094-46f9-8427-3b12e48aa308","content":"<p>accidental</p>"},{"id":"c212cf57-ddd0-4175-997f-f4701660972a","content":"<p>confident</p>"},{"id":"f0ef4f9e-b45c-4700-a2c6-d9e989c1e57f","content":"<p>expensive</p>"},{"id":"fb3bb610-e53d-4298-88c4-dc9c4ef34b2f","content":"<p>consistent</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["fb3bb610-e53d-4298-88c4-dc9c4ef34b2f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the challenge of generating electricity from ocean waves. In this context, "consistent" means steady or unchanging over time. The text introduces a challenge and then explains that wave power varies, or changes, unpredictably in ways that cause problems for electricity generation. This context conveys that the challenge being described is a lack of consistency.</p><p>Choice A is incorrect because the text introduces a challenge and then elaborates on it by emphasizing that the unpredictable nature of variations in ocean waves causes problems, which doesn&rsquo;t indicate that wave power isn&rsquo;t "accidental," or isn&rsquo;t happening unintentionally. It wouldn&rsquo;t make sense to describe waves&mdash;a natural occurrence&mdash;as happening intentionally. Choice B is incorrect because "confident" means having a feeling of self-assurance, and it wouldn&rsquo;t make sense to describe wave power itself in terms of either having or lacking a sense of confidence. Choice C is incorrect because the text introduces a challenge and then elaborates on it by emphasizing that the unpredictable nature of variations in ocean waves causes problems, which doesn&rsquo;t indicate that wave power isn&rsquo;t "expensive," or isn&rsquo;t costly. If anything, technological and planning problems might actually increase the expense of generating electricity from waves.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4b8244ca","external_id":"decacff8-b174-4cdb-9bcb-5c5714d5025d","vaultid":null,"uId":"34ecf8fa-e6d6-4e68-9fd0-b784d8b1bab7","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>One challenge of generating electricity from ocean waves is that wave power isn&rsquo;t <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>: it varies in unpredictable ways that pose technological and planning problems for electricity generation.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"93e22736-7094-46f9-8427-3b12e48aa308","content":"<p>accidental</p>"},{"id":"c212cf57-ddd0-4175-997f-f4701660972a","content":"<p>confident</p>"},{"id":"f0ef4f9e-b45c-4700-a2c6-d9e989c1e57f","content":"<p>expensive</p>"},{"id":"fb3bb610-e53d-4298-88c4-dc9c4ef34b2f","content":"<p>consistent</p>"}],"keys":["fb3bb610-e53d-4298-88c4-dc9c4ef34b2f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the challenge of generating electricity from ocean waves. In this context, \"consistent\" means steady or unchanging over time. The text introduces a challenge and then explains that wave power varies, or changes, unpredictably in ways that cause problems for electricity generation. This context conveys that the challenge being described is a lack of consistency.</p><p>Choice A is incorrect because the text introduces a challenge and then elaborates on it by emphasizing that the unpredictable nature of variations in ocean waves causes problems, which doesn&rsquo;t indicate that wave power isn&rsquo;t \"accidental,\" or isn&rsquo;t happening unintentionally. It wouldn&rsquo;t make sense to describe waves&mdash;a natural occurrence&mdash;as happening intentionally. Choice B is incorrect because \"confident\" means having a feeling of self-assurance, and it wouldn&rsquo;t make sense to describe wave power itself in terms of either having or lacking a sense of confidence. Choice C is incorrect because the text introduces a challenge and then elaborates on it by emphasizing that the unpredictable nature of variations in ocean waves causes problems, which doesn&rsquo;t indicate that wave power isn&rsquo;t \"expensive,\" or isn&rsquo;t costly. If anything, technological and planning problems might actually increase the expense of generating electricity from waves.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669213,"updateDate":1743430669213}$SATQ$::jsonb, 1743430669213, 1743430669213),
    ($SATQ$4c4db685$SATQ$, $SATQ$10aedcfb-dfe1-4eac-b1d2-89f7c794f9eb$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>On painter William H. Johnson&rsquo;s return to the United States in 1938 after a decade in Europe, his style underwent an abrupt transformation. <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">Turning away from landscapes painted in an expressionist style&mdash;a style that often involves using fluid, distorted shapes and thick, textured brushstrokes to express the artist&rsquo;s subjective experience of reality&mdash;Johnson began painting portraits of Black Americans in a bold new way.</span> Evocative of African sculpture and American and Scandinavian folk art, these portraits feature flat, deliberately oversimplified figures in a vibrant but limited color palette.</p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"436868f1-8b84-4ea1-8524-1d5ae8289954","content":"<p>It elaborates on the previous sentence&rsquo;s statement about a transitional moment in Johnson&rsquo;s artistic career.&nbsp;</p>"},{"id":"ecaefd80-09ca-4efc-9f99-bd666c1f6dde","content":"<p>It provides information about Johnson&rsquo;s travels in support of a claim about his artistic influences, which is advanced in the following sentence.&nbsp;</p>"},{"id":"3ac6cf94-8ea7-4c28-8bad-4b85d3d85164","content":"<p>It recounts a moment in Johnson&rsquo;s personal life that enabled the success of his subsequent career, which is summarized in the following sentence.</p>"},{"id":"e932ed83-b8d4-4f46-9898-cb1fc5e27d6d","content":"<p>It presents evidence that calls into question the previous sentence&rsquo;s characterization of Johnson&rsquo;s artistic development.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["436868f1-8b84-4ea1-8524-1d5ae8289954"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately describes the function of the underlined sentence in the text as a whole. The first sentence of the text indicates that Johnson returned to the US in 1938 at which time his painting style suddenly changed. The second sentence is underlined and gives more detail about this stylistic change, noting that his earlier work consisted largely of landscapes in an expressionist style and his new works were highly stylized portraits of Black Americans. In other words, the function of the underlined sentence is to elaborate on a transitional moment in Johnson&rsquo;s painting career.</p><p>Choice B is incorrect. Although the text does mention that Johnson spent a decade in Europe, it does not discuss what other travel Johnson might have done. Furthermore, although the text mentions African, American, and Scandinavian artistic elements in Johnson&rsquo;s work, it does not indicate that he traveled to different locations to learn about these practices. Choice C is incorrect because the text does not focus on Johnson&rsquo;s personal life nor does it address how successful his career was in general. Choice D is incorrect because, rather than call it into question, the underlined sentence continues the discussion of Johnson&rsquo;s career by adding further relevant detail of Johnson&rsquo;s artistic transformation.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4c4db685","external_id":"10aedcfb-dfe1-4eac-b1d2-89f7c794f9eb","vaultid":null,"uId":"27f12799-39fb-45b0-8ddc-23c62a3c6395","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>On painter William H. Johnson&rsquo;s return to the United States in 1938 after a decade in Europe, his style underwent an abrupt transformation. <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">Turning away from landscapes painted in an expressionist style&mdash;a style that often involves using fluid, distorted shapes and thick, textured brushstrokes to express the artist&rsquo;s subjective experience of reality&mdash;Johnson began painting portraits of Black Americans in a bold new way.</span> Evocative of African sculpture and American and Scandinavian folk art, these portraits feature flat, deliberately oversimplified figures in a vibrant but limited color palette.</p>","stem":"<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>","answerOptions":[{"id":"436868f1-8b84-4ea1-8524-1d5ae8289954","content":"<p>It elaborates on the previous sentence&rsquo;s statement about a transitional moment in Johnson&rsquo;s artistic career.&nbsp;</p>"},{"id":"ecaefd80-09ca-4efc-9f99-bd666c1f6dde","content":"<p>It provides information about Johnson&rsquo;s travels in support of a claim about his artistic influences, which is advanced in the following sentence.&nbsp;</p>"},{"id":"3ac6cf94-8ea7-4c28-8bad-4b85d3d85164","content":"<p>It recounts a moment in Johnson&rsquo;s personal life that enabled the success of his subsequent career, which is summarized in the following sentence.</p>"},{"id":"e932ed83-b8d4-4f46-9898-cb1fc5e27d6d","content":"<p>It presents evidence that calls into question the previous sentence&rsquo;s characterization of Johnson&rsquo;s artistic development.&nbsp;</p>"}],"keys":["436868f1-8b84-4ea1-8524-1d5ae8289954"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately describes the function of the underlined sentence in the text as a whole. The first sentence of the text indicates that Johnson returned to the US in 1938 at which time his painting style suddenly changed. The second sentence is underlined and gives more detail about this stylistic change, noting that his earlier work consisted largely of landscapes in an expressionist style and his new works were highly stylized portraits of Black Americans. In other words, the function of the underlined sentence is to elaborate on a transitional moment in Johnson&rsquo;s painting career.</p><p>Choice B is incorrect. Although the text does mention that Johnson spent a decade in Europe, it does not discuss what other travel Johnson might have done. Furthermore, although the text mentions African, American, and Scandinavian artistic elements in Johnson&rsquo;s work, it does not indicate that he traveled to different locations to learn about these practices. Choice C is incorrect because the text does not focus on Johnson&rsquo;s personal life nor does it address how successful his career was in general. Choice D is incorrect because, rather than call it into question, the underlined sentence continues the discussion of Johnson&rsquo;s career by adding further relevant detail of Johnson&rsquo;s artistic transformation.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323040,"updateDate":1730147323040}$SATQ$::jsonb, 1730147323040, 1730147323040),
    ($SATQ$4d1a9c0d$SATQ$, $SATQ$138cb6f2-d4f1-430b-9a21-b645929a5d0b$SATQ$::uuid, $SATQ$d018ce7e-fb3c-48b5-8b1d-35a021c1ea82$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Following the principles of community-based participatory research, tribal nations and research institutions are equal partners in health studies conducted on reservations. A collaboration between the Crow Tribe and Montana State University &shy;&shy;&shy;&shy;<span aria-hidden="true">______</span><span class="sr-only">blank</span> this model: tribal citizens worked alongside scientists to design the methodology and continue to assist in data collection.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"7e27cf1d-6d7d-445f-9850-f3943b875e39","content":"<p>circumvents</p>"},{"id":"30cda760-1abe-46cd-aa48-ea5a96d3bc44","content":"<p>eclipses</p>"},{"id":"c7f7c635-2557-4e71-9481-cbb5f32c6554","content":"<p>fabricates</p>"},{"id":"eb4664ce-d514-418b-b63e-80565c67f9c0","content":"<p>exemplifies</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["eb4664ce-d514-418b-b63e-80565c67f9c0"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the collaboration between the Crow Tribe and Montana State University. As used in this context, &ldquo;exemplifies&rdquo; means demonstrates. The text conveys how the Crow Tribe&ndash;Montana State University collaboration serves to illustrate the model of community-based participatory research introduced earlier in the text and expanded on later in the text.&nbsp;</p><p>Choice A is incorrect because referring to &ldquo;circumvents,&rdquo; or avoids, wouldn&rsquo;t make sense in context. The text suggests that the Crow Tribe&ndash;Montana State University collaboration serves as an example of the principles of community-based participatory research, not that the collaboration evades this model.&nbsp;Choice B is incorrect because referring to &ldquo;eclipses,&rdquo; or overshadows, wouldn&rsquo;t make sense in context. The text describes the Crow Tribe&ndash;Montana State University collaboration as an equal partnership, which indicates that it&rsquo;s an example of the community-based participatory research model, not that it overshadows the model.&nbsp;Choice C is incorrect because saying that the collaboration &ldquo;fabricates,&rdquo; or creates, the model wouldn&rsquo;t make sense in context. The text indicates that the Crow Tribe&ndash;Montana State University collaboration serves as an example of the model, not that it created the model.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-929-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$6ed7495c-d5e8-4baf-8d16-de3d130593b3$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4d1a9c0d","external_id":"138cb6f2-d4f1-430b-9a21-b645929a5d0b","vaultid":"d018ce7e-fb3c-48b5-8b1d-35a021c1ea82","uId":"2f2b895e-e198-4d4f-b3d5-7124f1917f50","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Following the principles of community-based participatory research, tribal nations and research institutions are equal partners in health studies conducted on reservations. A collaboration between the Crow Tribe and Montana State University &shy;&shy;&shy;&shy;<span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> this model: tribal citizens worked alongside scientists to design the methodology and continue to assist in data collection.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"7e27cf1d-6d7d-445f-9850-f3943b875e39","content":"<p>circumvents</p>"},{"id":"30cda760-1abe-46cd-aa48-ea5a96d3bc44","content":"<p>eclipses</p>"},{"id":"c7f7c635-2557-4e71-9481-cbb5f32c6554","content":"<p>fabricates</p>"},{"id":"eb4664ce-d514-418b-b63e-80565c67f9c0","content":"<p>exemplifies</p>"}],"keys":["eb4664ce-d514-418b-b63e-80565c67f9c0"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the collaboration between the Crow Tribe and Montana State University. As used in this context, &ldquo;exemplifies&rdquo; means demonstrates. The text conveys how the Crow Tribe&ndash;Montana State University collaboration serves to illustrate the model of community-based participatory research introduced earlier in the text and expanded on later in the text.&nbsp;</p><p>Choice A is incorrect because referring to &ldquo;circumvents,&rdquo; or avoids, wouldn&rsquo;t make sense in context. The text suggests that the Crow Tribe&ndash;Montana State University collaboration serves as an example of the principles of community-based participatory research, not that the collaboration evades this model.&nbsp;Choice B is incorrect because referring to &ldquo;eclipses,&rdquo; or overshadows, wouldn&rsquo;t make sense in context. The text describes the Crow Tribe&ndash;Montana State University collaboration as an equal partnership, which indicates that it&rsquo;s an example of the community-based participatory research model, not that it overshadows the model.&nbsp;Choice C is incorrect because saying that the collaboration &ldquo;fabricates,&rdquo; or creates, the model wouldn&rsquo;t make sense in context. The text indicates that the Crow Tribe&ndash;Montana State University collaboration serves as an example of the model, not that it created the model.&nbsp;</p>","parenttemplatename":"OSP-929-WIC","parenttemplateid":"","templateclusterid":"6ed7495c-d5e8-4baf-8d16-de3d130593b3","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959356,"updateDate":1691007959356}$SATQ$::jsonb, 1691007959356, 1691007959356),
    ($SATQ$4ed09415$SATQ$, $SATQ$a1fb437b-5ff4-416d-99c7-ab4b00b97f92$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Vadamalai Elangovan and Ganapathi Marimuthu showed that high moonlight intensity inhibits the activity of the greater short-nosed fruit bat (<em>Cynopterus sphinx</em>), a result explicable in terms of benefits and costs: greater lunar intensity may not enable the bats to increase foraging success enough to offset the higher chance of detection by predatory owls or hawks. Most other nocturnal mammals respond to lunar intensity variations similarly to greater short-nosed fruit bats, but mongoose lemurs (<em>Eulemur mongoz</em>) display the opposite pattern, as their heavy reliance on visual foraging results in a different balance of reward and risk.</p>$SATQ$, $SATQ$<p>Which choice best describes the overall structure of the text?</p>$SATQ$, $SATQ$[{"id":"fee069e9-bbda-43bd-b768-bfa33d7ba924","content":"<p>It discusses two different responses to the same natural phenomenon, explains why one of those responses occurs, and then suggests that the other response still needs to be explained.&nbsp;</p>"},{"id":"c199a929-deed-4ffc-9a2f-223b598092d9","content":"<p>It describes and accounts for a finding, characterizes the finding as representative of a general pattern, and then describes and accounts for an exception to that pattern.</p>"},{"id":"fab943a2-130c-41ab-b230-97b9d7395a85","content":"<p>It presents and explains a study result, indicates that the result is similar to the results of many other studies, and then attributes a conflicting study result to a difference in that study&rsquo;s methods.</p>"},{"id":"e2204294-fd2c-4ead-81db-b8da6b01fb98","content":"<p>It introduces an observation of a behavioral pattern, presents an explanation for the pattern, and then describes an exception to the pattern that casts doubt on that explanation.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["c199a929-deed-4ffc-9a2f-223b598092d9"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most accurately describes the overall structure of the text. The text begins by describing a study&rsquo;s finding about greater short-nosed fruit bats&mdash;namely, that high moonlight intensity inhibits the bats&rsquo; activity&mdash;and also accounts for that finding, stating that this occurs because the potential increase in foraging success that greater lunar intensity enables doesn&rsquo;t offset these bats&rsquo; increased vulnerability to predators (whose vision is also implied to become more acute under intense moonlight). The text goes on to characterize this finding as representative of a general pattern, stating that many nocturnal mammals behave similarly in response to changes in lunar intensity. The text concludes by describing an exception to this pattern, explaining that mongoose lemurs display an opposite tendency because they rely heavily on visual foraging. This strategy presumably would allow them to derive more benefit from greater lunar intensity than many other nocturnal mammals would, resulting in a "different balance of reward and risk" than exists for other nocturnal mammals. Therefore, the overall structure of the text is best described as a description and account of a finding, a characterization of that finding as representative of a pattern, and then a description and account of an exception to that pattern.</p><p>Choice A is incorrect. Although the text discusses two different responses to variations in moonlight intensity, explaining that as moonlight intensity increases, greater short-nosed fruit bats and many other nocturnal mammals decrease their foraging activity but mongoose lemurs increase their foraging activity, it doesn&rsquo;t leave one of these responses unexplained. The text accounts for both the typical response to increased lunar intensity (reduced activity due to predation risk) and the exception (increased activity due to a reliance on visual foraging) by making reference to a cost-benefit framework. Choice C is incorrect. Although the text presents a study&prime;s finding about the effect of increased lunar intensity on greater short-nosed fruit bats&rsquo; activity before going on to contrast this behavior with the fact that mongoose lemurs display the opposite response to increased lunar intensity, the text doesn&rsquo;t explicitly invoke other studies and doesn&rsquo;t attribute this difference in observed behavior to the fact that the study of greater short-nosed fruit bats used different methods than studies of mongoose lemurs did. Rather, the text explains that the different observed behaviors can be attributed to differences in species&rsquo; foraging strategies. Choice D is incorrect. Although the text characterizes the behavior of mongoose lemurs in response to increased lunar intensity as an exception to a pattern of behavior observed in other nocturnal mammal species, this exception doesn&rsquo;t cast any doubt on the explanation that is offered for the general pattern observed among other species. Instead, the text uses the same cost-benefit framework to explain why increased lunar intensity is associated with decreased activity by greater short-nosed fruit bats and other nocturnal mammals but with increased activity by mongoose lemurs.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"4ed09415","external_id":"a1fb437b-5ff4-416d-99c7-ab4b00b97f92","vaultid":null,"uId":"689c01c1-59f6-4675-b4bf-ac212217317e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Vadamalai Elangovan and Ganapathi Marimuthu showed that high moonlight intensity inhibits the activity of the greater short-nosed fruit bat (<em>Cynopterus sphinx</em>), a result explicable in terms of benefits and costs: greater lunar intensity may not enable the bats to increase foraging success enough to offset the higher chance of detection by predatory owls or hawks. Most other nocturnal mammals respond to lunar intensity variations similarly to greater short-nosed fruit bats, but mongoose lemurs (<em>Eulemur mongoz</em>) display the opposite pattern, as their heavy reliance on visual foraging results in a different balance of reward and risk.</p>","stem":"<p>Which choice best describes the overall structure of the text?</p>","answerOptions":[{"id":"fee069e9-bbda-43bd-b768-bfa33d7ba924","content":"<p>It discusses two different responses to the same natural phenomenon, explains why one of those responses occurs, and then suggests that the other response still needs to be explained.&nbsp;</p>"},{"id":"c199a929-deed-4ffc-9a2f-223b598092d9","content":"<p>It describes and accounts for a finding, characterizes the finding as representative of a general pattern, and then describes and accounts for an exception to that pattern.</p>"},{"id":"fab943a2-130c-41ab-b230-97b9d7395a85","content":"<p>It presents and explains a study result, indicates that the result is similar to the results of many other studies, and then attributes a conflicting study result to a difference in that study&rsquo;s methods.</p>"},{"id":"e2204294-fd2c-4ead-81db-b8da6b01fb98","content":"<p>It introduces an observation of a behavioral pattern, presents an explanation for the pattern, and then describes an exception to the pattern that casts doubt on that explanation.&nbsp;</p>"}],"keys":["c199a929-deed-4ffc-9a2f-223b598092d9"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most accurately describes the overall structure of the text. The text begins by describing a study&rsquo;s finding about greater short-nosed fruit bats&mdash;namely, that high moonlight intensity inhibits the bats&rsquo; activity&mdash;and also accounts for that finding, stating that this occurs because the potential increase in foraging success that greater lunar intensity enables doesn&rsquo;t offset these bats&rsquo; increased vulnerability to predators (whose vision is also implied to become more acute under intense moonlight). The text goes on to characterize this finding as representative of a general pattern, stating that many nocturnal mammals behave similarly in response to changes in lunar intensity. The text concludes by describing an exception to this pattern, explaining that mongoose lemurs display an opposite tendency because they rely heavily on visual foraging. This strategy presumably would allow them to derive more benefit from greater lunar intensity than many other nocturnal mammals would, resulting in a \"different balance of reward and risk\" than exists for other nocturnal mammals. Therefore, the overall structure of the text is best described as a description and account of a finding, a characterization of that finding as representative of a pattern, and then a description and account of an exception to that pattern.</p><p>Choice A is incorrect. Although the text discusses two different responses to variations in moonlight intensity, explaining that as moonlight intensity increases, greater short-nosed fruit bats and many other nocturnal mammals decrease their foraging activity but mongoose lemurs increase their foraging activity, it doesn&rsquo;t leave one of these responses unexplained. The text accounts for both the typical response to increased lunar intensity (reduced activity due to predation risk) and the exception (increased activity due to a reliance on visual foraging) by making reference to a cost-benefit framework. Choice C is incorrect. Although the text presents a study&prime;s finding about the effect of increased lunar intensity on greater short-nosed fruit bats&rsquo; activity before going on to contrast this behavior with the fact that mongoose lemurs display the opposite response to increased lunar intensity, the text doesn&rsquo;t explicitly invoke other studies and doesn&rsquo;t attribute this difference in observed behavior to the fact that the study of greater short-nosed fruit bats used different methods than studies of mongoose lemurs did. Rather, the text explains that the different observed behaviors can be attributed to differences in species&rsquo; foraging strategies. Choice D is incorrect. Although the text characterizes the behavior of mongoose lemurs in response to increased lunar intensity as an exception to a pattern of behavior observed in other nocturnal mammal species, this exception doesn&rsquo;t cast any doubt on the explanation that is offered for the general pattern observed among other species. Instead, the text uses the same cost-benefit framework to explain why increased lunar intensity is associated with decreased activity by greater short-nosed fruit bats and other nocturnal mammals but with increased activity by mongoose lemurs.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061190,"updateDate":1755117061190}$SATQ$::jsonb, 1755117061190, 1755117061190),
    ($SATQ$4eee64fa$SATQ$, $SATQ$9d7b4f85-3a2b-4e6a-bc64-ca9e159e8105$SATQ$::uuid, $SATQ$11a3416a-6eaf-4671-ac72-a2179e2ca98d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Space scientists Anna-Lisa Paul, Stephen M. Elardo, and Robert Ferl planted seeds of <em>Arabidopsis thaliana</em> in samples of lunar regolith&mdash;the surface material of the Moon&mdash;and, serving as a control group, in terrestrial soil. They found that while all the seeds germinated, the roots of the regolith-grown plants were stunted compared with those in the control group. Moreover, unlike the plants in the control group, the regolith-grown plants exhibited red pigmentation, reduced leaf size, and inhibited growth rates&mdash;indicators of stress that were corroborated by postharvest molecular analysis.</p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"21cbef56-5613-4f09-bdd5-99d206e4e9e6","content":"<p>It describes an experiment that addressed an unresolved question about the extent to which lunar regolith resembles terrestrial soils.</p>"},{"id":"bbb1d372-0126-479c-95e5-feb32f16517d","content":"<p>It compares two distinct methods of assessing indicators of stress in plants grown in a simulated lunar environment.</p>"},{"id":"01d73d1e-5380-4303-b10f-79d02627ce7b","content":"<p>It presents evidence in support of the hypothesis that seed germination in lunar habitats is an unattainable goal.</p>"},{"id":"ac92ab26-a5a3-47ea-a09d-faa59c65f698","content":"<p>It discusses the findings of a study that evaluated the effects of exposing a plant species to lunar soil conditions.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["ac92ab26-a5a3-47ea-a09d-faa59c65f698"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The text describes an experiment wherein space scientists compared plant growth in terrestrial and lunar soil conditions. It then discusses the findings of the study, including the fact that all the seeds germinated but that the plants grown in lunar soil exhibited signs of stress.</p><p>Choice A is incorrect. The text doesn&rsquo;t address this question, and never describes any specific characteristics of either soil. It merely describes the outcome of an experiment that exposed a plant species to lunar soil conditions. Choice B is incorrect. The text never compares methods of assessing indicators of stress&mdash;instead, it simply mentions several stress indicators observed in the study (red pigmentation, reduced leaf size, and inhibited growth rates). Choice C is incorrect. The text doesn&rsquo;t present any evidence that we could never achieve seed germination in lunar habitats, and in fact states that the seeds in the lunar soil did germinate.</p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-H010$SATQ$, $SATQ$$SATQ$, $SATQ$984dab64-995a-460f-9cb2-9e27c6276d6c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4eee64fa","external_id":"9d7b4f85-3a2b-4e6a-bc64-ca9e159e8105","vaultid":"11a3416a-6eaf-4671-ac72-a2179e2ca98d","uId":"b9b4834e-dc53-477b-ad36-547a276d1f78","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Space scientists Anna-Lisa Paul, Stephen M. Elardo, and Robert Ferl planted seeds of <em>Arabidopsis thaliana</em> in samples of lunar regolith&mdash;the surface material of the Moon&mdash;and, serving as a control group, in terrestrial soil. They found that while all the seeds germinated, the roots of the regolith-grown plants were stunted compared with those in the control group. Moreover, unlike the plants in the control group, the regolith-grown plants exhibited red pigmentation, reduced leaf size, and inhibited growth rates&mdash;indicators of stress that were corroborated by postharvest molecular analysis.</p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"21cbef56-5613-4f09-bdd5-99d206e4e9e6","content":"<p>It describes an experiment that addressed an unresolved question about the extent to which lunar regolith resembles terrestrial soils.</p>"},{"id":"bbb1d372-0126-479c-95e5-feb32f16517d","content":"<p>It compares two distinct methods of assessing indicators of stress in plants grown in a simulated lunar environment.</p>"},{"id":"01d73d1e-5380-4303-b10f-79d02627ce7b","content":"<p>It presents evidence in support of the hypothesis that seed germination in lunar habitats is an unattainable goal.</p>"},{"id":"ac92ab26-a5a3-47ea-a09d-faa59c65f698","content":"<p>It discusses the findings of a study that evaluated the effects of exposing a plant species to lunar soil conditions.</p>"}],"keys":["ac92ab26-a5a3-47ea-a09d-faa59c65f698"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The text describes an experiment wherein space scientists compared plant growth in terrestrial and lunar soil conditions. It then discusses the findings of the study, including the fact that all the seeds germinated but that the plants grown in lunar soil exhibited signs of stress.</p><p>Choice A is incorrect. The text doesn&rsquo;t address this question, and never describes any specific characteristics of either soil. It merely describes the outcome of an experiment that exposed a plant species to lunar soil conditions. Choice B is incorrect. The text never compares methods of assessing indicators of stress&mdash;instead, it simply mentions several stress indicators observed in the study (red pigmentation, reduced leaf size, and inhibited growth rates). Choice C is incorrect. The text doesn&rsquo;t present any evidence that we could never achieve seed germination in lunar habitats, and in fact states that the seeds in the lunar soil did germinate.</p>","parenttemplatename":"OSP-KA-TSP-H010","parenttemplateid":"","templateclusterid":"984dab64-995a-460f-9cb2-9e27c6276d6c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959375,"updateDate":1691007959375}$SATQ$::jsonb, 1691007959375, 1691007959375),
    ($SATQ$4fa7e50e$SATQ$, $SATQ$b5fa3821-faa3-4b0d-96c4-c13f51f9c305$SATQ$::uuid, $SATQ$93c9ba9e-58fb-4fe3-b9a1-011dd3e66894$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>According to a US tax policy expert, state taxes are <span aria-hidden="true">______</span><span class="sr-only">blank</span> other factors when considering an interstate move. Even significant differences in state taxation have almost no effect on most people&rsquo;s decisions, while differences in employment opportunities, housing availability, and climate are strong influences.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"cf955199-bc58-45fb-a033-ca4b18f2e4a3","content":"<p>consistent with</p>"},{"id":"af44b441-b650-4563-9dd5-4551cdf9ce18","content":"<p>representative of</p>"},{"id":"1d608fa4-eaca-43ed-85c1-906b9c5c143c","content":"<p>overshadowed by</p>"},{"id":"12afdf07-84e5-4f7a-b81d-f29846b9ee90","content":"<p>irrelevant to</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["1d608fa4-eaca-43ed-85c1-906b9c5c143c"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the factors that influence peoples&rsquo; decisions to move to a different state. As used in this context, &ldquo;overshadowed by&rdquo; means to be surpassed by or caused to seem less important than other factors affecting a move. The text indicates that, according to a US tax policy expert, when people think about an interstate move, state taxes have little effect on their decisions, while employment opportunities, housing availability, and climate have a very strong effect. This context suggests that people consider these other factors to be more important than state taxes.&nbsp;</p><p>Choice A is incorrect because the text indicates that state taxes aren&rsquo;t as important a consideration as other factors when people are thinking of moving to another state. The context doesn&rsquo;t suggest that state taxes are &ldquo;consistent with,&rdquo; or in agreement with these other factors.&nbsp;Choice B is incorrect because it wouldn&rsquo;t make sense in context to say that state taxes are &ldquo;representative of,&rdquo; or typical of, other factors. Taxes aren&rsquo;t an example of employment opportunities, housing availability, and climate, which are the other factors listed in the text. Choice D is incorrect because it wouldn&rsquo;t make sense in context to say that state taxes are &ldquo;irrelevant to,&rdquo; or unconnected or unimportant to other factors. State taxes are irrelevant to peoples&rsquo; decisions, not to other factors. In other words, although the text suggests that state taxes may be irrelevant to people considering a move to another state, the other factors mentioned in the text, such as employment opportunities, are unable to have an opinion about state taxes. Furthermore, the text indicates that significant differences in state taxes have almost no effect on peoples&rsquo; choices to move, but they aren&rsquo;t completely unimportant. </p>$SATQ$, false, 0, $SATQ$OSP-970-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$eec73283-9402-4cb0-b188-25f95ac5c8c5$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"4fa7e50e","external_id":"b5fa3821-faa3-4b0d-96c4-c13f51f9c305","vaultid":"93c9ba9e-58fb-4fe3-b9a1-011dd3e66894","uId":"dabab923-98f7-4c75-a8ec-cc4b978406b3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>According to a US tax policy expert, state taxes are <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> other factors when considering an interstate move. Even significant differences in state taxation have almost no effect on most people&rsquo;s decisions, while differences in employment opportunities, housing availability, and climate are strong influences.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"cf955199-bc58-45fb-a033-ca4b18f2e4a3","content":"<p>consistent with</p>"},{"id":"af44b441-b650-4563-9dd5-4551cdf9ce18","content":"<p>representative of</p>"},{"id":"1d608fa4-eaca-43ed-85c1-906b9c5c143c","content":"<p>overshadowed by</p>"},{"id":"12afdf07-84e5-4f7a-b81d-f29846b9ee90","content":"<p>irrelevant to</p>"}],"keys":["1d608fa4-eaca-43ed-85c1-906b9c5c143c"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the factors that influence peoples&rsquo; decisions to move to a different state. As used in this context, &ldquo;overshadowed by&rdquo; means to be surpassed by or caused to seem less important than other factors affecting a move. The text indicates that, according to a US tax policy expert, when people think about an interstate move, state taxes have little effect on their decisions, while employment opportunities, housing availability, and climate have a very strong effect. This context suggests that people consider these other factors to be more important than state taxes.&nbsp;</p><p>Choice A is incorrect because the text indicates that state taxes aren&rsquo;t as important a consideration as other factors when people are thinking of moving to another state. The context doesn&rsquo;t suggest that state taxes are &ldquo;consistent with,&rdquo; or in agreement with these other factors.&nbsp;Choice B is incorrect because it wouldn&rsquo;t make sense in context to say that state taxes are &ldquo;representative of,&rdquo; or typical of, other factors. Taxes aren&rsquo;t an example of employment opportunities, housing availability, and climate, which are the other factors listed in the text. Choice D is incorrect because it wouldn&rsquo;t make sense in context to say that state taxes are &ldquo;irrelevant to,&rdquo; or unconnected or unimportant to other factors. State taxes are irrelevant to peoples&rsquo; decisions, not to other factors. In other words, although the text suggests that state taxes may be irrelevant to people considering a move to another state, the other factors mentioned in the text, such as employment opportunities, are unable to have an opinion about state taxes. Furthermore, the text indicates that significant differences in state taxes have almost no effect on peoples&rsquo; choices to move, but they aren&rsquo;t completely unimportant. </p>","parenttemplatename":"OSP-970-WIC","parenttemplateid":"","templateclusterid":"eec73283-9402-4cb0-b188-25f95ac5c8c5","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959357,"updateDate":1691007959357}$SATQ$::jsonb, 1691007959357, 1691007959357),
    ($SATQ$5127fc1e$SATQ$, $SATQ$1f888d4d-cf99-4016-a73b-088ef836dc5a$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>The north celestial pole (NCP)&mdash;the fixed point around which stars in the Northern Hemisphere (including the Sun) appear to rotate&mdash;is discernible only at night. Inspired by the navigational strategies of some insects and birds, researchers devised a method for locating the NCP in daytime using skylight polarization, which occurs as atmospheric particles scatter sunlight. A polarimetric camera captures images of polarization patterns, which rotate as the Sun&rsquo;s position in the sky changes; temporal variances across images can then be used to determine an observer&rsquo;s latitude and bearing relative to the NCP.</p>$SATQ$, $SATQ$<p>Which choice best describes the overall structure of the text?</p>$SATQ$, $SATQ$[{"id":"9a7bf483-0d44-4c80-acc8-bc6f26941e09","content":"<p>It illustrates how most navigational tools utilize the NCP, recounts how researchers discovered that certain animals are able to navigate without using the NCP, and then proposes that this discovery could be used to avoid problems in navigation associated with reliance on the NCP.</p>"},{"id":"e7f7c0aa-524e-48d8-9fab-f631b648fdbd","content":"<p>It presents a celestial-based method of navigation, enumerates the comparative benefits of an alternative method used by certain animals that is based on an unrelated natural occurrence, and then indicates how researchers assessed the relative accuracy of the two methods.</p>"},{"id":"8d31e2fd-6f66-402c-8d67-90a9c7f63271","content":"<p>It explains how the NCP is typically located, emphasizes a key difference between how humans and certain animals use the NCP for navigation, and then suggests an alternative way of using the NCP to improve existing navigational instruments.</p>"},{"id":"f2523f37-62d3-4d91-8a6b-923c122f006f","content":"<p>It notes an obstacle to observing an astronomical phenomenon, mentions a navigational ability of certain animals that inspired a solution to that obstacle, and then explains how researchers used an optical device to mimic that ability.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["f2523f37-62d3-4d91-8a6b-923c122f006f"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it accurately describes the overall structure of the text. The text begins by pointing out an obstacle to observing the astronomical phenomenon of the NCP: the NCP is visible only at night. The text then indicates that, inspired by the ability of some insects and birds to navigate using visualizations of polarized sunlight, researchers devised a way to locate the NCP during daylight. The text then indicates that the researchers mimicked the insects&rsquo; and birds&rsquo; polarized-light visualization capabilities using a polarimetric camera. Thus, the text notes an obstacle to observing an astronomical phenomenon, mentions a navigational ability of certain animals that inspired a solution to that obstacle, and then explains how researchers used an optical device to mimic that ability.</p><p>Choice A is incorrect. Although it&rsquo;s reasonable to conjecture that humans have used the NCP for navigation, the text doesn&rsquo;t indicate this is the case, let alone that the NCP is relevant to a majority of navigational tools. Furthermore, the text doesn&rsquo;t state that researchers discovered that insects and birds navigate without the NCP; rather, it indicates that it&rsquo;s known that some animals navigate by using skylight polarization to locate the NCP during the day and that this knowledge inspired the method the researchers devised. Choice B is incorrect. Although it&rsquo;s reasonable to conjecture that humans have used the NCP for navigation, the text doesn&rsquo;t state that this is the case. Furthermore, the text discusses how some animals&rsquo; use of navigational strategies based on the same celestial occurrence served as the inspiration for the researchers&rsquo; polarized-light approach, not as the basis for a comparison of the relative effectiveness of animal and human methods of navigation. Choice C is incorrect. Although the text implies that humans have typically been able to locate the NCP visually at night and indicates that some animals use the NCP to navigate, the text doesn&rsquo;t state that humans use the NCP for navigation. The text therefore doesn&rsquo;t emphasize a difference between how humans and animals use the NCP for this purpose. Furthermore, the text doesn&rsquo;t suggest that existing navigational instruments will be augmented with polarimetric technologies.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"5127fc1e","external_id":"1f888d4d-cf99-4016-a73b-088ef836dc5a","vaultid":null,"uId":"a6f59ea2-5571-474d-a655-ec5ccc5f3224","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>The north celestial pole (NCP)&mdash;the fixed point around which stars in the Northern Hemisphere (including the Sun) appear to rotate&mdash;is discernible only at night. Inspired by the navigational strategies of some insects and birds, researchers devised a method for locating the NCP in daytime using skylight polarization, which occurs as atmospheric particles scatter sunlight. A polarimetric camera captures images of polarization patterns, which rotate as the Sun&rsquo;s position in the sky changes; temporal variances across images can then be used to determine an observer&rsquo;s latitude and bearing relative to the NCP.</p>","stem":"<p>Which choice best describes the overall structure of the text?</p>","answerOptions":[{"id":"9a7bf483-0d44-4c80-acc8-bc6f26941e09","content":"<p>It illustrates how most navigational tools utilize the NCP, recounts how researchers discovered that certain animals are able to navigate without using the NCP, and then proposes that this discovery could be used to avoid problems in navigation associated with reliance on the NCP.</p>"},{"id":"e7f7c0aa-524e-48d8-9fab-f631b648fdbd","content":"<p>It presents a celestial-based method of navigation, enumerates the comparative benefits of an alternative method used by certain animals that is based on an unrelated natural occurrence, and then indicates how researchers assessed the relative accuracy of the two methods.</p>"},{"id":"8d31e2fd-6f66-402c-8d67-90a9c7f63271","content":"<p>It explains how the NCP is typically located, emphasizes a key difference between how humans and certain animals use the NCP for navigation, and then suggests an alternative way of using the NCP to improve existing navigational instruments.</p>"},{"id":"f2523f37-62d3-4d91-8a6b-923c122f006f","content":"<p>It notes an obstacle to observing an astronomical phenomenon, mentions a navigational ability of certain animals that inspired a solution to that obstacle, and then explains how researchers used an optical device to mimic that ability.</p>"}],"keys":["f2523f37-62d3-4d91-8a6b-923c122f006f"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it accurately describes the overall structure of the text. The text begins by pointing out an obstacle to observing the astronomical phenomenon of the NCP: the NCP is visible only at night. The text then indicates that, inspired by the ability of some insects and birds to navigate using visualizations of polarized sunlight, researchers devised a way to locate the NCP during daylight. The text then indicates that the researchers mimicked the insects&rsquo; and birds&rsquo; polarized-light visualization capabilities using a polarimetric camera. Thus, the text notes an obstacle to observing an astronomical phenomenon, mentions a navigational ability of certain animals that inspired a solution to that obstacle, and then explains how researchers used an optical device to mimic that ability.</p><p>Choice A is incorrect. Although it&rsquo;s reasonable to conjecture that humans have used the NCP for navigation, the text doesn&rsquo;t indicate this is the case, let alone that the NCP is relevant to a majority of navigational tools. Furthermore, the text doesn&rsquo;t state that researchers discovered that insects and birds navigate without the NCP; rather, it indicates that it&rsquo;s known that some animals navigate by using skylight polarization to locate the NCP during the day and that this knowledge inspired the method the researchers devised. Choice B is incorrect. Although it&rsquo;s reasonable to conjecture that humans have used the NCP for navigation, the text doesn&rsquo;t state that this is the case. Furthermore, the text discusses how some animals&rsquo; use of navigational strategies based on the same celestial occurrence served as the inspiration for the researchers&rsquo; polarized-light approach, not as the basis for a comparison of the relative effectiveness of animal and human methods of navigation. Choice C is incorrect. Although the text implies that humans have typically been able to locate the NCP visually at night and indicates that some animals use the NCP to navigate, the text doesn&rsquo;t state that humans use the NCP for navigation. The text therefore doesn&rsquo;t emphasize a difference between how humans and animals use the NCP for this purpose. Furthermore, the text doesn&rsquo;t suggest that existing navigational instruments will be augmented with polarimetric technologies.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669204,"updateDate":1743430669204}$SATQ$::jsonb, 1743430669204, 1743430669204),
    ($SATQ$5179fd36$SATQ$, $SATQ$c518470f-82cc-4e18-994d-a1186ef6afbc$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Urban planning expert Francisco Lara-Valencia and colleagues have argued that managing environmental matters along the US-Mexico border <span aria-hidden="true">______</span><span class="sr-only">blank</span> coordination between the two countries&rsquo; governments. Since ecosystems extend across the border, actions taken on one side can have environmental effects on the other side, making international cooperation essential.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"2d624118-f0b6-41d1-84f2-5d1749229269","content":"<p>requires</p>"},{"id":"239977e0-0d48-4b97-90d2-d26302f57cf3","content":"<p>praises</p>"},{"id":"da01e3ad-d555-4ba6-b2ed-8de32a01b2de","content":"<p>reports</p>"},{"id":"89a7f3e5-72cf-474e-9504-24f46631835d","content":"<p>advises</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["2d624118-f0b6-41d1-84f2-5d1749229269"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of environmental management along the US and Mexican border. In this context, "requires" means needs in order to perform a task. The text indicates that because ecosystems span the border, actions taken by the government on one side of the border can affect the environment in the nation on the other side of the border, which makes international cooperation crucial. In other words, because actions on one side of the US and Mexican border can affect the other side of the border, managing environmental matters along the border requires coordination between the two governments.</p><p>Choice B is incorrect because "praises" in this context would mean to express a favorable judgment, but the text doesn&rsquo;t describe approval expressed by anyone, and it wouldn&rsquo;t make sense to say that environmental management itself praises intergovernmental coordination. Choice C is incorrect. In this context, "reports" would mean gives an account. Although coordination between the US and Mexican governments likely would involve some sort of reporting, the text doesn&rsquo;t describe any such practice. Choice D is incorrect. In this context, "advises" would mean recommends a course of action, and although governments can advise one another, it wouldn&rsquo;t make sense to say that environmental management itself makes recommendations.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"5179fd36","external_id":"c518470f-82cc-4e18-994d-a1186ef6afbc","vaultid":null,"uId":"b790033c-731d-40f9-9aa0-a23ef00d4eca","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Urban planning expert Francisco Lara-Valencia and colleagues have argued that managing environmental matters along the US-Mexico border <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> coordination between the two countries&rsquo; governments. Since ecosystems extend across the border, actions taken on one side can have environmental effects on the other side, making international cooperation essential.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"2d624118-f0b6-41d1-84f2-5d1749229269","content":"<p>requires</p>"},{"id":"239977e0-0d48-4b97-90d2-d26302f57cf3","content":"<p>praises</p>"},{"id":"da01e3ad-d555-4ba6-b2ed-8de32a01b2de","content":"<p>reports</p>"},{"id":"89a7f3e5-72cf-474e-9504-24f46631835d","content":"<p>advises</p>"}],"keys":["2d624118-f0b6-41d1-84f2-5d1749229269"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of environmental management along the US and Mexican border. In this context, \"requires\" means needs in order to perform a task. The text indicates that because ecosystems span the border, actions taken by the government on one side of the border can affect the environment in the nation on the other side of the border, which makes international cooperation crucial. In other words, because actions on one side of the US and Mexican border can affect the other side of the border, managing environmental matters along the border requires coordination between the two governments.</p><p>Choice B is incorrect because \"praises\" in this context would mean to express a favorable judgment, but the text doesn&rsquo;t describe approval expressed by anyone, and it wouldn&rsquo;t make sense to say that environmental management itself praises intergovernmental coordination. Choice C is incorrect. In this context, \"reports\" would mean gives an account. Although coordination between the US and Mexican governments likely would involve some sort of reporting, the text doesn&rsquo;t describe any such practice. Choice D is incorrect. In this context, \"advises\" would mean recommends a course of action, and although governments can advise one another, it wouldn&rsquo;t make sense to say that environmental management itself makes recommendations.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323032,"updateDate":1730147323032}$SATQ$::jsonb, 1730147323032, 1730147323032),
    ($SATQ$52fe862a$SATQ$, $SATQ$de4db60e-8686-45b9-9f67-b2f3504f4c15$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Researcher Lucy Salazar is using radiocarbon dating to study Machu Picchu, an ancient Incan fortress in the Andes Mountains. She and her colleagues have found that the site&rsquo;s age differs from the <span aria-hidden="true">______</span><span class="sr-only">blank</span> estimate: it is approximately 20 years older than scholars thought when first encountering Machu Picchu in 1911.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"db4b89ef-c777-447d-9647-860ec2b77e3a","content":"<p>genuine</p>"},{"id":"4ed31e85-8b72-4337-bed5-d823aa9eb907","content":"<p>intentional</p>"},{"id":"cf8f3c75-70f6-4bfa-bd9e-74699e8ae2ec","content":"<p>independent</p>"},{"id":"6e60bb1b-214e-488b-93ff-d4bf3d27405c","content":"<p>original</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["6e60bb1b-214e-488b-93ff-d4bf3d27405c"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the dating of Machu Picchu. In this context, "original" means first or initial. The text indicates that Lucy Salazar and her colleagues have determined the age of Machu Picchu and that the age differs from another estimate of the site&rsquo;s age, explaining that the site is about 20 years older than scholars thought in 1911 when they initially encountered Machu Picchu. In other words, Salazar and her team found that the site&rsquo;s age differs from the first estimate.</p><p>Choice A is incorrect. The text&rsquo;s structure indicates that the missing word describes the estimate made by scholars when they first encountered Machu Picchu in 1911 in relation to the age determined by Salazar and her colleagues. It wouldn&rsquo;t make sense to suggest that the estimate by earlier scholars was "genuine," or actual and true, while the one by Salazar&rsquo;s team wasn&rsquo;t, since the text treats the finding by Salazar&rsquo;s team as true and as invalidating the earlier estimate ("it is approximately 20 years older than scholars thought"). Choice B is incorrect. The text&rsquo;s structure indicates that the missing word describes the estimate made by scholars when they first encountered Machu Picchu in 1911 in relation to the age determined by Salazar and her colleagues. It wouldn&rsquo;t make sense to suggest that the estimate by earlier scholars was "intentional," or done on purpose, while the one by Salazar&rsquo;s team wasn&rsquo;t; the text indicates that Salazar and her colleagues were deliberately using radiocarbon dating to study Machu Picchu. Choice C is incorrect. The text&rsquo;s structure indicates that the missing word describes the estimate made by scholars when they first encountered Machu Picchu in 1911 in relation to the age determined by Salazar and her colleagues. There&rsquo;s no reason to suggest that the estimate by earlier scholars was "independent," or not controlled by or affiliated with others, while the one by Salazar&rsquo;s team wasn&rsquo;t; there&rsquo;s no mention of any outside influence on the work by Salazar and her team or by scholars in 1911.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"52fe862a","external_id":"de4db60e-8686-45b9-9f67-b2f3504f4c15","vaultid":null,"uId":"7a703646-fe02-44d2-948c-00fee010c379","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Researcher Lucy Salazar is using radiocarbon dating to study Machu Picchu, an ancient Incan fortress in the Andes Mountains. She and her colleagues have found that the site&rsquo;s age differs from the <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> estimate: it is approximately 20 years older than scholars thought when first encountering Machu Picchu in 1911.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"db4b89ef-c777-447d-9647-860ec2b77e3a","content":"<p>genuine</p>"},{"id":"4ed31e85-8b72-4337-bed5-d823aa9eb907","content":"<p>intentional</p>"},{"id":"cf8f3c75-70f6-4bfa-bd9e-74699e8ae2ec","content":"<p>independent</p>"},{"id":"6e60bb1b-214e-488b-93ff-d4bf3d27405c","content":"<p>original</p>"}],"keys":["6e60bb1b-214e-488b-93ff-d4bf3d27405c"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of the dating of Machu Picchu. In this context, \"original\" means first or initial. The text indicates that Lucy Salazar and her colleagues have determined the age of Machu Picchu and that the age differs from another estimate of the site&rsquo;s age, explaining that the site is about 20 years older than scholars thought in 1911 when they initially encountered Machu Picchu. In other words, Salazar and her team found that the site&rsquo;s age differs from the first estimate.</p><p>Choice A is incorrect. The text&rsquo;s structure indicates that the missing word describes the estimate made by scholars when they first encountered Machu Picchu in 1911 in relation to the age determined by Salazar and her colleagues. It wouldn&rsquo;t make sense to suggest that the estimate by earlier scholars was \"genuine,\" or actual and true, while the one by Salazar&rsquo;s team wasn&rsquo;t, since the text treats the finding by Salazar&rsquo;s team as true and as invalidating the earlier estimate (\"it is approximately 20 years older than scholars thought\"). Choice B is incorrect. The text&rsquo;s structure indicates that the missing word describes the estimate made by scholars when they first encountered Machu Picchu in 1911 in relation to the age determined by Salazar and her colleagues. It wouldn&rsquo;t make sense to suggest that the estimate by earlier scholars was \"intentional,\" or done on purpose, while the one by Salazar&rsquo;s team wasn&rsquo;t; the text indicates that Salazar and her colleagues were deliberately using radiocarbon dating to study Machu Picchu. Choice C is incorrect. The text&rsquo;s structure indicates that the missing word describes the estimate made by scholars when they first encountered Machu Picchu in 1911 in relation to the age determined by Salazar and her colleagues. There&rsquo;s no reason to suggest that the estimate by earlier scholars was \"independent,\" or not controlled by or affiliated with others, while the one by Salazar&rsquo;s team wasn&rsquo;t; there&rsquo;s no mention of any outside influence on the work by Salazar and her team or by scholars in 1911.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323033,"updateDate":1730147323033}$SATQ$::jsonb, 1730147323033, 1730147323033),
    ($SATQ$5336f2e4$SATQ$, $SATQ$1e70c390-74ee-4d74-94fa-daff0424d92b$SATQ$::uuid, $SATQ$5bc9dc2d-835e-435f-9d75-bd6d87846473$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Zora Neale Hurston&rsquo;s 1921 short story &ldquo;John Redding Goes to Sea.&rdquo; John is a child who lives in a town in the woods.</p>
<p style="padding-left:1em;">Perhaps ten-year-old John was puzzling to the folk there in the Florida woods for he was an imaginative child and fond of day-dreams. The St. John River flowed a scarce three hundred feet from his back door. On its banks at this point grow numerous palms, luxuriant magnolias and bay trees. On the bosom of the stream float millions of delicately colored hyacinths. <span role="region" aria-label="Referenced Content"><u>[John Redding] loved to wander down to the water&rsquo;s edge, and, casting in dry twigs, watch them sail away down stream to Jacksonville, the sea, the wide world and [he] wanted to follow them.</u></span></p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"b06b26c4-06c9-4163-b0ff-a98e1a36468f","content":"<p>It provides an extended description of a location that John likes to visit.</p>"},{"id":"dcd6ce90-b375-4f23-91ed-4cb834a213b6","content":"<p>It reveals that some residents of John&rsquo;s town are confused by his behavior.</p>"},{"id":"e0a43ac1-4276-453d-ae57-10378030459e","content":"<p>It illustrates the uniqueness of John&rsquo;s imagination compared to the imaginations of other children.</p>"},{"id":"ebd9ebdf-4444-422b-b8bd-b7a229456c86","content":"<p>It suggests that John longs to experience a larger life outside the Florida woods.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["ebd9ebdf-4444-422b-b8bd-b7a229456c86"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it accurately describes how the underlined sentence functions in the text as a whole. The text establishes that John has a strong imagination and then goes on to describe the St. John River near John&rsquo;s home in the Florida woods. The underlined sentence depicts John sending twigs sailing down the river while he imagines them reaching &ldquo;Jacksonville, the sea, the wide world,&rdquo; where he wishes he could follow. This suggests that John longs to expand his life experiences beyond the Florida woods. </p><p>Choice A is incorrect because the second and third sentences of the text provide an extended description of the riverbank where John likes to go, whereas the underlined sentence describes what John does at that location. Choice B is incorrect because the first sentence of the text suggests that John&rsquo;s behavior &ldquo;was puzzling&rdquo; to others around him, whereas the underlined sentence concerns the content of John&rsquo;s imaginings. Choice C is incorrect because the underlined sentence elaborates on John&rsquo;s imagination but doesn&rsquo;t mention any other children to whom John could be compared. </p>$SATQ$, false, 0, $SATQ$OSP-014-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$f5e343e5-526e-462a-9c08-b323e13ffeca$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"5336f2e4","external_id":"1e70c390-74ee-4d74-94fa-daff0424d92b","vaultid":"5bc9dc2d-835e-435f-9d75-bd6d87846473","uId":"5cc8a1c1-01e8-4a02-9ae8-a2b0498e7246","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>The following text is adapted from Zora Neale Hurston&rsquo;s 1921 short story &ldquo;John Redding Goes to Sea.&rdquo; John is a child who lives in a town in the woods.</p>\n<p style=\"padding-left:1em;\">Perhaps ten-year-old John was puzzling to the folk there in the Florida woods for he was an imaginative child and fond of day-dreams. The St. John River flowed a scarce three hundred feet from his back door. On its banks at this point grow numerous palms, luxuriant magnolias and bay trees. On the bosom of the stream float millions of delicately colored hyacinths. <span role=\"region\" aria-label=\"Referenced Content\"><u>[John Redding] loved to wander down to the water&rsquo;s edge, and, casting in dry twigs, watch them sail away down stream to Jacksonville, the sea, the wide world and [he] wanted to follow them.</u></span></p>","stem":"<p>Which choice best describes the function of the underlined sentence in the text as a whole?</p>","answerOptions":[{"id":"b06b26c4-06c9-4163-b0ff-a98e1a36468f","content":"<p>It provides an extended description of a location that John likes to visit.</p>"},{"id":"dcd6ce90-b375-4f23-91ed-4cb834a213b6","content":"<p>It reveals that some residents of John&rsquo;s town are confused by his behavior.</p>"},{"id":"e0a43ac1-4276-453d-ae57-10378030459e","content":"<p>It illustrates the uniqueness of John&rsquo;s imagination compared to the imaginations of other children.</p>"},{"id":"ebd9ebdf-4444-422b-b8bd-b7a229456c86","content":"<p>It suggests that John longs to experience a larger life outside the Florida woods.</p>"}],"keys":["ebd9ebdf-4444-422b-b8bd-b7a229456c86"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it accurately describes how the underlined sentence functions in the text as a whole. The text establishes that John has a strong imagination and then goes on to describe the St. John River near John&rsquo;s home in the Florida woods. The underlined sentence depicts John sending twigs sailing down the river while he imagines them reaching &ldquo;Jacksonville, the sea, the wide world,&rdquo; where he wishes he could follow. This suggests that John longs to expand his life experiences beyond the Florida woods. </p><p>Choice A is incorrect because the second and third sentences of the text provide an extended description of the riverbank where John likes to go, whereas the underlined sentence describes what John does at that location. Choice B is incorrect because the first sentence of the text suggests that John&rsquo;s behavior &ldquo;was puzzling&rdquo; to others around him, whereas the underlined sentence concerns the content of John&rsquo;s imaginings. Choice C is incorrect because the underlined sentence elaborates on John&rsquo;s imagination but doesn&rsquo;t mention any other children to whom John could be compared. </p>","parenttemplatename":"OSP-014-TSP","parenttemplateid":"","templateclusterid":"f5e343e5-526e-462a-9c08-b323e13ffeca","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959315,"updateDate":1691007959315}$SATQ$::jsonb, 1691007959315, 1691007959315),
    ($SATQ$53542eb5$SATQ$, $SATQ$16996808-9d20-4460-88c0-c738319a84a9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Shoppers can help keep money cycling within a community by making purchases at small local businesses instead of large retailers. Some cities are <span aria-hidden="true">______</span><span class="sr-only">blank</span> programs to encourage this behavior, establishing reward points and other incentives for shopping at small businesses.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"6523876e-02af-4e5d-8fc5-eea91248407b","content":"<p>instituting</p>"},{"id":"2b6e71b9-c871-4dba-9fa1-cca933f0f8ae","content":"<p>occupying</p>"},{"id":"94039f16-5a88-4c5e-bbd6-e96ff35fbad4","content":"<p>underestimating</p>"},{"id":"8454e887-7344-4110-9191-e7fdae4ab83a","content":"<p>encountering</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["6523876e-02af-4e5d-8fc5-eea91248407b"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of programs that encourage money to cycle within a community. In this context, "instituting" means initiating. The text indicates that making purchases at small local businesses can help keep money cycling within a community. The text goes on to state that some cities are establishing incentives to promote small business shopping. This context supports the idea that some cities are instituting programs to encourage this consumer behavior.</p><p>Choice B is incorrect because saying that some cities are "occupying," or forcibly holding possession or control of, programs that encourage shoppers to make purchases at small local businesses wouldn&rsquo;t make sense in context. The text doesn&rsquo;t discuss who controls these programs but instead indicates that some cities are establishing incentives that encourage shoppers to make purchases at small local businesses. Furthermore, it wouldn&rsquo;t make sense to say that a city is occupying a program. Choice C is incorrect because nothing in the text suggests that cities are "underestimating," or failing to understand the value of, programs that encourage consumers to shop at small local businesses. The text indicates that some cities are establishing incentives to encourage small business shopping, which suggests that these cities understand the value of such programs. Choice D is incorrect because saying that some cities are "encountering," or coming into contact with, programs that encourage consumers to shop at small local businesses wouldn&rsquo;t make sense in context. The text indicates that some cities are already establishing incentives to encourage shoppers to make purchases at small businesses. This context suggests that the cities are instituting the programs, not that they are encountering them.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"53542eb5","external_id":"16996808-9d20-4460-88c0-c738319a84a9","vaultid":null,"uId":"d2c31d87-db7d-48f6-9ff9-37f3d889bf9d","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Shoppers can help keep money cycling within a community by making purchases at small local businesses instead of large retailers. Some cities are <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> programs to encourage this behavior, establishing reward points and other incentives for shopping at small businesses.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"6523876e-02af-4e5d-8fc5-eea91248407b","content":"<p>instituting</p>"},{"id":"2b6e71b9-c871-4dba-9fa1-cca933f0f8ae","content":"<p>occupying</p>"},{"id":"94039f16-5a88-4c5e-bbd6-e96ff35fbad4","content":"<p>underestimating</p>"},{"id":"8454e887-7344-4110-9191-e7fdae4ab83a","content":"<p>encountering</p>"}],"keys":["6523876e-02af-4e5d-8fc5-eea91248407b"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of programs that encourage money to cycle within a community. In this context, \"instituting\" means initiating. The text indicates that making purchases at small local businesses can help keep money cycling within a community. The text goes on to state that some cities are establishing incentives to promote small business shopping. This context supports the idea that some cities are instituting programs to encourage this consumer behavior.</p><p>Choice B is incorrect because saying that some cities are \"occupying,\" or forcibly holding possession or control of, programs that encourage shoppers to make purchases at small local businesses wouldn&rsquo;t make sense in context. The text doesn&rsquo;t discuss who controls these programs but instead indicates that some cities are establishing incentives that encourage shoppers to make purchases at small local businesses. Furthermore, it wouldn&rsquo;t make sense to say that a city is occupying a program. Choice C is incorrect because nothing in the text suggests that cities are \"underestimating,\" or failing to understand the value of, programs that encourage consumers to shop at small local businesses. The text indicates that some cities are establishing incentives to encourage small business shopping, which suggests that these cities understand the value of such programs. Choice D is incorrect because saying that some cities are \"encountering,\" or coming into contact with, programs that encourage consumers to shop at small local businesses wouldn&rsquo;t make sense in context. The text indicates that some cities are already establishing incentives to encourage shoppers to make purchases at small businesses. This context suggests that the cities are instituting the programs, not that they are encountering them.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323033,"updateDate":1730147323033}$SATQ$::jsonb, 1730147323033, 1730147323033),
    ($SATQ$5444db38$SATQ$, $SATQ$faee6021-41fd-493b-ae3e-d83005275eb7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>To demonstrate that the integrity of underground metal pipes can be assessed without unearthing the pipes, engineer Aroba Saleem and colleagues <span aria-hidden="true">______</span><span class="sr-only">blank</span> the tendency of some metals&rsquo; internal magnetic fields to alter under stress: the team showed that such alterations can be measured from a distance and can reveal concentrations of stress in the pipes.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"0bacd622-4226-444c-9c69-ffbb36042044","content":"<p>hypothesized</p>"},{"id":"c587603a-e846-4fb7-a535-fc40669f5755","content":"<p>discounted</p>"},{"id":"ef95eefb-82dd-43f0-a6fe-929fd6179822","content":"<p>redefined</p>"},{"id":"f016075c-b77d-4c21-b2ba-b5fc10551fb4","content":"<p>exploited</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["f016075c-b77d-4c21-b2ba-b5fc10551fb4"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of using magnetism to detect stress in buried metal pipes. In this context, "exploited" means made productive use of. The text indicates that the magnetic fields of some metals change under stress and that Saleem and colleagues showed that it is possible to measure those changes from a distance, thereby demonstrating that the integrity of underground metal pipes can be evaluated without having to unearth them. This context thus indicates that Saleem and colleagues made productive use of, or exploited, this tendency of the metals&rsquo; magnetic fields.</p><p>Choice A is incorrect because in this context, "hypothesized" would mean made a tentative assumption to be evaluated in a study or experiment. Although Saleem and colleagues may have had one or more hypotheses for these experiments, the text presents the information about the tendency of some metals&rsquo; magnetic fields to change under stress as a known fact that the researchers made productive use of, not as a hypothesis to be evaluated. The text after the colon indicates that the researchers were not evaluating whether such changes occur but whether those changes can be measured at a distance. Choice B is incorrect because in this context, "discounted" would mean downplayed or ignored, but the text does not suggest that Saleem and colleagues minimized or ignored the tendency of the magnetic fields of some metals to change under stress. Rather, the text indicates that this tendency is the basis for Saleem and colleagues&rsquo; method of assessing the pipes&rsquo; integrity. Choice C is incorrect because nothing in the text indicates that Saleem and colleagues "redefined," or reevaluated or reformulated, the tendency of some metals&rsquo; magnetic fields to change under stress. Instead, the text indicates that the researchers made use of that tendency to demonstrate that it is possible to evaluate the integrity of underground pipes without unearthing them.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"5444db38","external_id":"faee6021-41fd-493b-ae3e-d83005275eb7","vaultid":null,"uId":"f0377b5f-421b-4042-bf49-b88edefad19f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>To demonstrate that the integrity of underground metal pipes can be assessed without unearthing the pipes, engineer Aroba Saleem and colleagues <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the tendency of some metals&rsquo; internal magnetic fields to alter under stress: the team showed that such alterations can be measured from a distance and can reveal concentrations of stress in the pipes.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"0bacd622-4226-444c-9c69-ffbb36042044","content":"<p>hypothesized</p>"},{"id":"c587603a-e846-4fb7-a535-fc40669f5755","content":"<p>discounted</p>"},{"id":"ef95eefb-82dd-43f0-a6fe-929fd6179822","content":"<p>redefined</p>"},{"id":"f016075c-b77d-4c21-b2ba-b5fc10551fb4","content":"<p>exploited</p>"}],"keys":["f016075c-b77d-4c21-b2ba-b5fc10551fb4"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer because it most logically completes the text&rsquo;s discussion of using magnetism to detect stress in buried metal pipes. In this context, \"exploited\" means made productive use of. The text indicates that the magnetic fields of some metals change under stress and that Saleem and colleagues showed that it is possible to measure those changes from a distance, thereby demonstrating that the integrity of underground metal pipes can be evaluated without having to unearth them. This context thus indicates that Saleem and colleagues made productive use of, or exploited, this tendency of the metals&rsquo; magnetic fields.</p><p>Choice A is incorrect because in this context, \"hypothesized\" would mean made a tentative assumption to be evaluated in a study or experiment. Although Saleem and colleagues may have had one or more hypotheses for these experiments, the text presents the information about the tendency of some metals&rsquo; magnetic fields to change under stress as a known fact that the researchers made productive use of, not as a hypothesis to be evaluated. The text after the colon indicates that the researchers were not evaluating whether such changes occur but whether those changes can be measured at a distance. Choice B is incorrect because in this context, \"discounted\" would mean downplayed or ignored, but the text does not suggest that Saleem and colleagues minimized or ignored the tendency of the magnetic fields of some metals to change under stress. Rather, the text indicates that this tendency is the basis for Saleem and colleagues&rsquo; method of assessing the pipes&rsquo; integrity. Choice C is incorrect because nothing in the text indicates that Saleem and colleagues \"redefined,\" or reevaluated or reformulated, the tendency of some metals&rsquo; magnetic fields to change under stress. Instead, the text indicates that the researchers made use of that tendency to demonstrate that it is possible to evaluate the integrity of underground pipes without unearthing them.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323040,"updateDate":1730147323040}$SATQ$::jsonb, 1730147323040, 1730147323040),
    ($SATQ$54804e10$SATQ$, $SATQ$2e3a13e3-1586-4dd0-bc91-532ea8ad3efe$SATQ$::uuid, $SATQ$0a5082f2-9e28-44bf-94c1-80f4a76c9c35$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While scholars believe many Mesoamerican cities influenced each other, direct evidence of such influence is difficult to ascertain. However, recent excavations in a sector of Tikal (Guatemala) unearthed a citadel that shows <span aria-hidden="true">______</span><span class="sr-only">blank</span> Teotihuac&aacute;n (Mexico) architecture&mdash;including a near replica of a famed Teotihuac&aacute;n temple&mdash;providing tangible evidence of outside influence in portions of Tikal.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"662360a6-726c-4200-ba29-63dc3c1f1590","content":"<p>refinements of</p>"},{"id":"e7b9af7a-c5bb-4a6b-aee8-d395a627c534","content":"<p>precursors of</p>"},{"id":"fe6e5f45-3938-4969-bff9-75e1163bb804","content":"<p>commonalities with</p>"},{"id":"35c82a50-5db8-45d9-a8fb-b39721efcb72","content":"<p>animosities toward</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["fe6e5f45-3938-4969-bff9-75e1163bb804"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of architectural influences among Mesoamerican cities. In this context, &ldquo;commonalities with&rdquo; means similarities to or shared attributes with. The text indicates that a recently discovered citadel in Tikal includes a close imitation of a famous temple in Teotihuac&aacute;n (another Mesoamerican city) and other evidence of Teotihuac&aacute;n influence, which suggests that the citadel possesses features that resemble architectural features found in Teotihuac&aacute;n. This context thus indicates that the Tikal citadel shows commonalities with Teotihuac&aacute;n architecture. </p><p>Choice A is incorrect because there&rsquo;s nothing in the text that suggests that the Tikal citadel shows &ldquo;refinements of,&rdquo; or improvements on, Teotihuac&aacute;n architecture. Although the text suggests that the architecture of Teotihuac&aacute;n influenced the architecture of the Tikal citadel, and although it&rsquo;s possible that later architectural designs could make improvements on earlier designs, the text doesn&rsquo;t discuss whether, in imitating Teotihuac&aacute;n architecture, the Tikal citadel&rsquo;s builders improved on it.&nbsp;Choice B is incorrect because describing the citadel in Tikal as showing &ldquo;precursors of&rdquo; Teotihuac&aacute;n architecture&mdash;or features that preceded and foreshadowed those of Teotihuac&aacute;n architecture&mdash;would imply the opposite of what the text suggests about the relationship between the architecture found in Tikal and Teotihuac&aacute;n. The text claims that the discovery of similarities between the Tikal citadel and the architecture of Teotihuac&aacute;n, including a replica of a temple in Teotihuac&aacute;n, provides evidence of outside influences on Tikal architecture. If the Tikal citadel was influenced by Teotihuac&aacute;n architecture, then the Teotihuac&aacute;n architecture must predate the citadel, not the other way around. In this context, therefore, it wouldn&rsquo;t make sense to say that the Tikal citadel shows precursors of Teotihuac&aacute;n architecture.&nbsp;Choice D is incorrect because the text discusses how the citadel in Tikal indicates the influence of Teotihuac&aacute;n architecture, which implies that the makers of the Tikal citadel likely admired aspects of Teotihuac&aacute;n architecture enough to imitate it. Thus, there&rsquo;s no reason to think that the Tikal citadel provides evidence of the Tikal people&rsquo;s &ldquo;animosities toward,&rdquo; or feelings of strong dislike or hostility toward, Teotihuac&aacute;n architecture.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-KA-WIC-H008$SATQ$, $SATQ$$SATQ$, $SATQ$a05bf5e9-3063-4d17-8b07-046be9a72f2c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"54804e10","external_id":"2e3a13e3-1586-4dd0-bc91-532ea8ad3efe","vaultid":"0a5082f2-9e28-44bf-94c1-80f4a76c9c35","uId":"4ed97a96-4473-4010-852b-a06d65461d4e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While scholars believe many Mesoamerican cities influenced each other, direct evidence of such influence is difficult to ascertain. However, recent excavations in a sector of Tikal (Guatemala) unearthed a citadel that shows <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> Teotihuac&aacute;n (Mexico) architecture&mdash;including a near replica of a famed Teotihuac&aacute;n temple&mdash;providing tangible evidence of outside influence in portions of Tikal.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"662360a6-726c-4200-ba29-63dc3c1f1590","content":"<p>refinements of</p>"},{"id":"e7b9af7a-c5bb-4a6b-aee8-d395a627c534","content":"<p>precursors of</p>"},{"id":"fe6e5f45-3938-4969-bff9-75e1163bb804","content":"<p>commonalities with</p>"},{"id":"35c82a50-5db8-45d9-a8fb-b39721efcb72","content":"<p>animosities toward</p>"}],"keys":["fe6e5f45-3938-4969-bff9-75e1163bb804"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of architectural influences among Mesoamerican cities. In this context, &ldquo;commonalities with&rdquo; means similarities to or shared attributes with. The text indicates that a recently discovered citadel in Tikal includes a close imitation of a famous temple in Teotihuac&aacute;n (another Mesoamerican city) and other evidence of Teotihuac&aacute;n influence, which suggests that the citadel possesses features that resemble architectural features found in Teotihuac&aacute;n. This context thus indicates that the Tikal citadel shows commonalities with Teotihuac&aacute;n architecture. </p><p>Choice A is incorrect because there&rsquo;s nothing in the text that suggests that the Tikal citadel shows &ldquo;refinements of,&rdquo; or improvements on, Teotihuac&aacute;n architecture. Although the text suggests that the architecture of Teotihuac&aacute;n influenced the architecture of the Tikal citadel, and although it&rsquo;s possible that later architectural designs could make improvements on earlier designs, the text doesn&rsquo;t discuss whether, in imitating Teotihuac&aacute;n architecture, the Tikal citadel&rsquo;s builders improved on it.&nbsp;Choice B is incorrect because describing the citadel in Tikal as showing &ldquo;precursors of&rdquo; Teotihuac&aacute;n architecture&mdash;or features that preceded and foreshadowed those of Teotihuac&aacute;n architecture&mdash;would imply the opposite of what the text suggests about the relationship between the architecture found in Tikal and Teotihuac&aacute;n. The text claims that the discovery of similarities between the Tikal citadel and the architecture of Teotihuac&aacute;n, including a replica of a temple in Teotihuac&aacute;n, provides evidence of outside influences on Tikal architecture. If the Tikal citadel was influenced by Teotihuac&aacute;n architecture, then the Teotihuac&aacute;n architecture must predate the citadel, not the other way around. In this context, therefore, it wouldn&rsquo;t make sense to say that the Tikal citadel shows precursors of Teotihuac&aacute;n architecture.&nbsp;Choice D is incorrect because the text discusses how the citadel in Tikal indicates the influence of Teotihuac&aacute;n architecture, which implies that the makers of the Tikal citadel likely admired aspects of Teotihuac&aacute;n architecture enough to imitate it. Thus, there&rsquo;s no reason to think that the Tikal citadel provides evidence of the Tikal people&rsquo;s &ldquo;animosities toward,&rdquo; or feelings of strong dislike or hostility toward, Teotihuac&aacute;n architecture.&nbsp;</p>","parenttemplatename":"OSP-KA-WIC-H008","parenttemplateid":"","templateclusterid":"a05bf5e9-3063-4d17-8b07-046be9a72f2c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959378,"updateDate":1691007959378}$SATQ$::jsonb, 1691007959378, 1691007959378)
